using UnityEngine;

// 1.2~ 망자의 전령 대사 221줄 · 보스 재회 한 줄 8줄 (Herald · StoryDirector) 번역
// tools: docs/review/2026-10-16-한판더-글.md 에서 뽑아 만든 표 (글을 고치면 문서와 함께)
public static partial class LocTable
{
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    static void AddHeraldLinesBoot() { if (!SceneFlow.DeferStartup(5, AddHeraldLines)) AddHeraldLines(); }      // 1.6.1~ 켤 때는 로딩 화면이 뜬 뒤로 (큰 함수는 불릴 때 통째로 JIT 되므로 작은 함수에서 미룸 · SceneFlow)

    static void AddHeraldLines()
    {
        void A(string key, string ko, string en, string ja, string zh) { if (!Entries.ContainsKey(key)) Entries[key] = E(ko, en, ja, zh); }

        A("herald.boss.slime.leap.h", "킹 슬라임이 뛰어오르면 땅에 그림자 원이 먼저 떨어진다. 원 밖으로 — 그리고 내려앉은 자리의 산성 웅덩이는 밟지 마라.", "When King Slime leaps, its shadow lands first. Step out of the circle, and keep off the acid it leaves where it comes down.", "キングスライムが跳ぶ時、影の円が先に地に落ちる。円の外へ。降りた跡の酸の水たまりも踏むな。", "史莱姆王跃起时，影子会先落到地上。走出那个圆，也别踩它落地后留下的酸液。");
        A("herald.boss.slime.blobs.h", "점액 방울은 부채꼴로 다섯. 방울과 방울 사이가 네 길이다. 왕이 작아지면 두 번째 부채가 엇갈려 온다.", "The slime blobs come five in a fan. Your path is the gap between them. Once the king has shrunk, a second fan follows, offset from the first.", "粘液の玉は扇形に五つ。玉と玉の隙間がお前の道だ。王が小さくなれば、二つ目の扇がずれて来る。", "粘液球呈扇形五颗，球与球之间就是你的路。王缩小之后，第二道扇形会错开袭来。");
        A("herald.boss.slime.roll.h", "굴러올 길을 먼저 보여 준다. 길 위에 서 있지 말고 옆으로 비켜라. 지나간 자리의 산성 자국도 길이다 — 밟지 않는 쪽으로.", "It shows you the path before it rolls. Don't stand on it; step aside. The acid trail it leaves behind is part of that path, too.", "転がる道筋を先に見せてくる。その上に立つな、横へ退け。通った跡の酸もまた道だ。踏まぬ側へ。", "它会先亮出翻滚的路线。别站在线上，往旁边躲。滚过之处留下的酸迹也算路线，别踩。");
        A("herald.boss.slime.barrier.h", "산성 범람은 아홉 초. 비는 넓게, 덩어리는 셋만 튕긴다. 넓은 것은 흐름을 읽고, 셋은 눈으로 쫓아라.", "The Acid Deluge lasts nine seconds. The rain falls wide; only three lumps bounce. Read the rain's drift, and keep your eyes on the three.", "酸の氾濫は九秒。雨は広く、跳ねる塊は三つだけ。広いものは流れを読み、三つは目で追え。", "酸性泛滥持续九秒。酸雨落得广，弹跳的黏块只有三个。读懂雨势，用眼盯紧那三个。");
        A("herald.boss.slime.contact", "킹 슬라임은 맞을수록 작아지고 빨라진다. 작아졌다고 가까이 가지 마라 — 그때가 가장 빠르다.", "King Slime shrinks and quickens with every wound. Don't close in because it got small; that is when it is fastest.", "キングスライムは傷つくほど小さく、速くなる。小さくなったからと近づくな。その時こそ最も速い。", "史莱姆王受伤越多，就越小越快。别因为它变小就靠近，那正是它最快的时候。");
        A("herald.boss.slime.split.h", "체력이 반이 꺾이면 왕은 작은 것 넷을 뱉는다. 넷에 눈을 빼앗기지 마라 — 끝내야 할 것은 하나다.", "At half its health the king spits out four little ones. Don't let the four steal your eyes; there is still only one to finish.", "体力が半分で王は小さな四匹を吐く。四匹に目を奪われるな。終わらせるべきは一つだ。", "生命减半时，王会吐出四只小的。别被那四只夺去目光，要了结的只有一个。");
        A("herald.boss.lich.orbs.h", "영혼구는 쏘면 터진다. 쫓기기 싫다면 먼저 쏴라. 피해 다니기만 해도 일곱 초면 제자리에서 터진다 — 그 자리에 네가 없기만 하면 된다.", "Soul orbs burst when shot. If you'd rather not be chased, shoot first. Or outrun them: in seven seconds they burst where they are, so long as you are not there.", "魂の球は撃てば弾ける。追われたくなければ先に撃て。逃げ続けても七秒でその場で弾ける。そこにお前がいなければいい。", "灵魂球打了就会炸。不想被追，就先开枪。一直躲也行，七秒后它会在原地炸开，只要你不在那儿。");
        A("herald.boss.lich.prison.h", "뼈 감옥에는 틈이 하나 있다. 벽을 넘지 마라, 넘으면 맞는다. 틈을 찾아 걸어 나가라 — 안쪽은 곧 터진다.", "The bone prison has one gap. Don't climb the wall; the wall bites. Find the gap and walk out, for the inside is about to burst.", "骨の牢獄には隙間が一つ。壁を越えるな、越えれば喰われる。隙間を探して歩み出よ。内側はすぐ弾ける。", "骨之牢笼有一道缺口。别翻墙，翻就会受伤。找到缺口走出去，里面马上就要炸了。");
        A("herald.boss.lich.tombs.h", "저주 묘비는 부서지기 전까지 세 초마다 터진다. 피하는 것은 답이 아니다. 묘비를 먼저 부숴라 — 둘, 왕이 약해지면 셋.", "A cursed tombstone bursts every three seconds until it is broken. Dodging is no answer. Break the stones first: two of them, three once the king is weakened.", "呪いの墓石は壊すまで三秒ごとに弾ける。避けるのは答えではない。先に墓石を壊せ。二つ、王が弱れば三つだ。", "诅咒墓碑在被击毁前每三秒炸一次。躲不是办法。先毁掉墓碑：两座，王虚弱后是三座。");
        A("herald.boss.lich.arrows.h", "왕이 사라지면 네게서 떨어진 곳에 다시 선다. 그리고 사방으로 화살. 사라진 순간 멈춰 서서 어디서 나타나는지 보라 — 화살은 왕을 중심으로 퍼진다.", "When the king vanishes, he reappears away from you, and arrows fly in every direction. The moment he fades, stop and watch where he returns; the arrows spread from him.", "王が消えれば、お前から離れた所に再び立つ。そして四方へ矢。消えた瞬間に足を止め、どこに現れるか見よ。矢は王を中心に広がる。", "王消失后会在离你较远处重新出现，随即箭射四方。他消失的那一刻停下来看他在哪现身，箭是以他为中心散开的。");
        A("herald.boss.lich.ritual.h", "망자의 의식 — 왕은 무적이 되고 등불 셋을 띄운다. 스물두 초 안에 셋을 모두 꺼라. 그러면 왕이 네 초 동안 휘청이고, 그때의 한 방은 반 배 더 아프다.", "The Rite of the Dead: the king becomes untouchable and raises three lanterns. Put out all three within twenty-two seconds, and he staggers for four, taking half again as much from every blow.", "死者の儀式。王は無敵となり、灯籠を三つ浮かべる。二十二秒の内に三つすべてを消せ。さすれば王は四秒よろめき、その間の一撃は半分増しで痛む。", "亡者仪式：王进入无敌，升起三盏灯。二十二秒内把三盏全熄灭，他就会踉跄四秒，那时每一击都多痛五成。");
        A("herald.boss.lich.ritual2.h", "등불을 하나만 남겨 두면 아무 일도 일어나지 않는다. 등불은 셋이 함께 꺼져야 뜻이 있다. 하나를 쫓다 둘을 잊지 마라.", "Leave even one lantern burning and nothing happens. The three only matter together. Don't chase one and forget the other two.", "灯籠を一つでも残せば何も起こらない。三つ揃って消えてこそ意味がある。一つを追って二つを忘れるな。", "只要留下一盏灯，什么都不会发生。三盏一起熄才有意义。别追着一盏，忘了另外两盏。");
        A("herald.boss.lich.barrier.h", "망자의 묘역은 열다섯 초다. 결계는 화면보다 넓다 — 벽을 찾지 말고 경고를 읽어라. 모든 공격이 먼저 자리를 알려 준다.", "The Graveyard of the Dead lasts fifteen seconds. The barrier is wider than your screen, so don't look for a wall; read the warnings. Every attack announces its place first.", "亡者の墓域は十五秒。結界は画面より広い。壁を探すな、警告を読め。すべての攻撃は先に場所を告げる。", "亡者墓域持续十五秒。结界比屏幕还宽，别找墙，去读预警。每一次攻击都会先告诉你落在哪。");
        A("herald.boss.lich.contact", "왕의 몸에 닿아 쓰러졌다. 리치 왕은 멀리서 싸우는 자다 — 네가 가까웠다는 건 순간이동 뒤였다는 뜻이다. 그가 다시 서는 자리를 보고 한 걸음 물러나라.", "You fell to the king's own touch. The Lich King fights from afar; being that close means he had just blinked beside you. Watch where he lands, and take one step back.", "王の体に触れて倒れた。リッチ王は遠くで戦う者。近かったということは、瞬間移動の直後だったのだ。王が再び立つ場所を見て、一歩退け。", "你死于与王相触。巫妖王是远战之人，离得那么近，说明他刚瞬移到你身边。看清他落脚的位置，退后一步。");
        A("herald.boss.demon.charge.h", "화염 돌진은 굵은 길을 먼저 그린다. 길이 굵은 만큼 늦게 피하면 늦다. 그어지는 순간 옆으로.", "The Flame Charge draws its wide path first. As wide as the path, so late is too late. Step aside the instant it is drawn.", "炎の突進は太い道を先に描く。道が太い分、遅れて避ければ間に合わぬ。描かれた瞬間に横へ。", "火焰冲锋会先画出一条宽路。路有多宽，躲晚了就有多迟。线一画出就往旁边闪。");
        A("herald.boss.demon.dash.h", "돌진은 한 번으로 끝나지 않는다. 짧은 예고로 여러 번 — 첫 번째를 피하고 멈추면 두 번째가 온다. 계속 움직여라.", "The charge doesn't end with one. Several follow, each with only a short warning. Dodge the first and stand still, and the second finds you. Keep moving.", "突進は一度で終わらぬ。短い予告で何度も来る。一度目を避けて止まれば二度目が来る。動き続けよ。", "冲锋不会只有一次。短短的预警后接连再来。躲过第一下就停住，第二下就会找上你。别停。");
        A("herald.boss.demon.meteor.h", "운석은 일곱, 네 둘레에 차례로 떨어진다. 떨어질 자리는 한 박자 먼저 붉게 찬다. 그 원이 차기 전에 나가라 — 하나씩, 서두르지 말고.", "Seven meteors fall around you, one after another. Each spot fills red a beat before it lands. Leave the circle before it fills, one at a time, without panic.", "隕石は七つ、お前の周りに順に落ちる。落ちる場所は一拍先に赤く満ちる。円が満ちる前に出よ。一つずつ、慌てずに。", "七颗陨石依次落在你周围。落点会提前一拍泛红填满。在圆填满前走出去，一颗一颗，别慌。");
        A("herald.boss.demon.wave.h", "화염 파동의 불 고리에는 틈이 셋 있다. 고리를 뛰어넘을 수는 없다. 가장 가까운 틈으로 — 틈은 고리와 함께 퍼져 나간다.", "The ring of the Fire Wave has three gaps. You cannot jump the ring. Make for the nearest gap; it travels outward with the ring.", "炎の波の火輪には隙間が三つ。輪は飛び越えられぬ。最も近い隙間へ。隙間は輪と共に広がっていく。", "火焰波的火环上有三道缺口。你跳不过火环。奔向最近的缺口，缺口会随火环一起向外扩。");
        A("herald.boss.demon.wings.h", "체력의 삼분의 일이 깎이면 군주는 날개를 편다. 그 순간 둘레를 밀어내는 충격파. 날개가 펴진다는 알림이 뜨면, 그에게서 멀어져라.", "Lose a third of his health and the lord spreads his wings, and a shockwave hurls everything near him away. When the warning says his wings are opening, be far from him.", "体力の三分の一が削れた時、君主は翼を広げる。その瞬間、周りを押し出す衝撃波。翼を広げる報せが出たら、奴から離れよ。", "他的生命被削去三分之一时，领主会展开双翼，那一瞬周围都会被冲击波推开。看到展翼的提示，就远离他。");
        A("herald.boss.demon.barrage.h", "하늘로 떠오르면 부채꼴 불탄이 세 번, 마지막에는 네 번. 부채는 엇갈린다 — 한 부채의 틈이 다음 부채의 탄이다. 쏘는 사이사이에 옮겨 서라.", "When he rises into the air, fans of fire come three times, four at the end. The fans are offset: the gap in one is the bullet in the next. Shift between volleys.", "空へ浮かべば扇形の火弾が三度、最後には四度。扇はずれて来る。一つの扇の隙間が次の扇の弾だ。撃つ合間に立ち位置を変えよ。", "他升到空中后，扇形火弹来三次，最后阶段四次。扇形是错开的：这一扇的缺口就是下一扇的弹。趁射击间隙换位。");
        A("herald.boss.demon.slam.h", "내려찍기는 네가 선 자리에 큰 원을 그린다. 원 밖으로 나가는 것만으로는 반이다 — 떨어진 자리에 불길이 잠시 남는다. 돌아오지 마라.", "The Dive Slam draws a great circle where you stand. Leaving the circle is only half of it; flames linger where he lands. Don't come back for a while.", "急降下はお前の立つ場所に大きな円を描く。円の外へ出るだけでは半分だ。降りた跡に炎がしばし残る。戻るな。", "俯冲砸地会在你站的地方画一个大圆。走出圆只算做了一半，他落地处还会残留火焰。别回去。");
        A("herald.boss.demon.lava.h", "마지막 삼분의 일에서 가장자리는 용암이 된다. 싸움터가 좁아지고 모든 공격이 빨라진다. 가운데를 지켜라 — 벽에 등을 대는 버릇이 여기서 죽인다.", "In the last third, the edges turn to lava. The arena shrinks and every attack quickens. Hold the middle; the habit of backing to a wall is what kills here.", "最後の三分の一で、縁は溶岩になる。戦場は狭まり、すべての攻撃が速まる。中央を守れ。壁に背を預ける癖が、ここでは命を奪う。", "最后三分之一，场地边缘会化为熔岩。战场缩小，所有攻击都加快。守住中央，靠墙的习惯在这里会要你的命。");
        A("herald.boss.demon.barrier.h", "연옥 낙화 — 하늘이 열다섯 초 동안 무너진다. 떨어지는 것은 모두 먼저 자리를 알린다. 알린 자리에서 비켜 서는 것, 그것뿐이다.", "Purgatory's Fall: the sky comes down for fifteen seconds. Everything that falls announces its place first. Step off the announced ground; that is all there is to it.", "煉獄落火。空が十五秒崩れ落ちる。落ちるものは皆、先に場所を告げる。告げられた地から退くこと、それだけだ。", "炼狱落火：天空崩落十五秒。坠落之物都会先宣告落点。离开被宣告的地面，仅此而已。");
        A("herald.boss.mirror.strike.h", "거울 공격은 네 평타를 흉내 낸다. 네가 아는 무기다 — 사거리도, 간격도. 네 손이 익힌 것을 거꾸로 피하라.", "The Mirror Strike copies your own attack: a weapon you know, its reach and its rhythm. Dodge what your own hands have learned, in reverse.", "鏡の攻撃はお前の通常攻撃を真似る。お前の知る武器だ。射程も、間合いも。自分の手が覚えたものを、逆から避けよ。", "镜之攻击模仿你的普通攻击。那是你熟悉的武器，射程与节奏都一样。把你双手学会的东西，倒过来躲开。");
        A("herald.boss.mirror.clones.h", "분신은 셋, 진짜는 하나. 가짜는 맞지 않는다. 셋이 모두 조각을 쏜 뒤 가짜는 스스로 깨진다 — 구별하려 애쓰지 마라, 네 공격이 꽂히는 쪽이 진짜다.", "Three images, one real. Blows pass through the false ones. All three fire shards, then the false shatter on their own. Don't strain to tell them apart; the one your attacks bite is the true one.", "分身は三つ、本物は一つ。偽物には当たらぬ。三つが破片を放った後、偽物は自ら砕ける。見分けようと悩むな。お前の攻撃が刺さる方が本物だ。", "分身三个，真身一个。假的打不中。三个都射出镜片后，假的会自行碎裂。别费力分辨，你的攻击能打中的那个就是真的。");
        A("herald.boss.mirror.cross.h", "낙인은 네 곁으로 순간이동한 뒤 제자리에 십자 광선. 군주가 곁에 나타나면 대각선으로 빠져라 — 십자의 네 팔 사이가 비어 있다.", "The brand: he blinks to your side, then burns a cross where he stands. When the sovereign appears beside you, slip away on the diagonal; the space between the cross's four arms is empty.", "烙印。お前の傍へ瞬間移動し、その場に十字の光線。君主が傍に現れたら斜めへ抜けよ。十字の四本の腕の間は空いている。", "烙印：他瞬移到你身旁，然后在原地打出十字光线。君主出现在身边时，沿对角线脱出，十字四臂之间是空的。");
        A("herald.boss.mirror.rings.h", "거울 조각 고리는 세 겹, 엇갈려 퍼진다. 첫 겹의 틈으로 들어갔다면 둘째 겹의 틈은 다른 자리다. 겹마다 다시 찾아라.", "The shard rings spread in three layers, each offset from the last. The gap you took in the first is not where the second's lies. Find it anew for every layer.", "鏡の破片の輪は三重、ずれて広がる。一重目の隙間を抜けたなら、二重目の隙間は別の場所だ。重ごとに探し直せ。", "镜片环分三层，错开扩散。你钻过第一层的缺口，第二层的缺口却在别处。每一层都要重新找。");
        A("herald.boss.mirror.ult.h", "군주는 네 필살기도 흉내 낸다. 네가 그것을 쓸 때 적이 어디서 죽었는지 떠올려라 — 그 자리에 네가 서 있으면 안 된다.", "The sovereign mimics your Ultimate as well. Remember where your enemies died when you used it; that is where you must not stand.", "君主はお前の必殺技も真似る。お前がそれを放つ時、敵がどこで死んだか思い出せ。そこにお前が立っていてはならぬ。", "君主也会模仿你的必杀技。想想你放必杀时敌人死在哪里，那正是你不能站的地方。");
        A("herald.boss.mirror.memory.h", "되비친 기억 — 이 판에서 네가 가장 많이 쓴 공격이 거꾸로 온다. 결과 화면의 「준 피해」 첫 줄, 그것이 다음 판에 네게 돌아올 것이다.", "Reflected Memory: the attack you used most this run comes back at you. The first line under Damage Dealt on the result screen is what will return to you next time.", "映し返された記憶。このプレイでお前が最も使った攻撃が、逆に向かってくる。結果画面の「与ダメージ」の一行目、それが次にお前へ返ってくる。", "映照之忆：本局你用得最多的攻击会反过来袭向你。结果画面「造成伤害」的第一行，就是下一局要还给你的东西。");
        A("herald.boss.mirror.barrier.h", "거울의 방은 열다섯 초. 둘레의 거울이 차례로 너를 노려 광선을 되쏘고, 깨진 조각이 쏟아진다. 거울 하나가 빛나면 그 거울과 너를 잇는 선에서 비켜라.", "The Hall of Mirrors lasts fifteen seconds. Mirrors around you take turns aiming beams at you while shards rain down. When a mirror lights up, step off the line between it and you.", "鏡の間は十五秒。周りの鏡が順にお前を狙って光線を返し、割れた破片が降る。鏡が一つ光ったら、その鏡とお前を結ぶ線から退け。", "镜之间持续十五秒。四周的镜子轮流瞄准你反射光束，碎片倾泻而下。哪面镜子亮起，就离开它与你之间的那条线。");
        A("herald.boss.mirror.contact", "거울에 몸이 닿아 쓰러졌다. 군주는 네 곁으로 오기를 좋아한다 — 낙인 전에, 분신 전에. 그가 곁에 선 순간은 늘 떠날 순간이다.", "You fell to the mirror's touch. The sovereign likes to come close, before the brand, before the clones. The moment he stands beside you is always the moment to leave.", "鏡に触れて倒れた。君主はお前の傍へ来ることを好む。烙印の前に、分身の前に。奴が傍に立つ瞬間は、常に去るべき瞬間だ。", "你死于与镜相触。君主喜欢贴近你，在烙印之前，在分身之前。他站到你身边的那一刻，永远是该离开的那一刻。");
        A("herald.boss.any.gauge.h", "결계 게이지는 네가 때릴 때마다 찬다 — 약한 여러 번보다 센 한 방이 훨씬 많이. 세 초를 쉬면 게이지는 조금씩 식는다. 결계가 뜨는 때는 네가 정하는 것이다.", "The barrier gauge fills with every blow you land, and one heavy strike fills it far more than many light ones. Rest three seconds and it cools a little. When the barrier comes is, in the end, your choice.", "結界のゲージはお前が殴るたびに満ちる。弱い連打より強い一撃の方がずっと多く。三秒休めばゲージは少し冷める。結界が来る時は、お前が決めているのだ。", "结界槽随你每一击而填满，一记重击远比许多轻击填得多。歇三秒，它就会稍稍冷却。结界何时降临，终究是你决定的。");
        A("herald.mob.bonespike.h", "뼈 가시는 네 발밑에서 솟는다. 가시가 노리는 것은 네가 선 자리, 네가 아니다. 서 있던 자리를 버려라.", "Bone spikes rise from under your feet. They aim at where you stand, not at you. Give up the ground you stood on.", "骨の棘はお前の足元から突き出る。棘が狙うのはお前の立つ場所であって、お前ではない。立っていた地を捨てよ。", "骨刺从你脚下冒出。它瞄准的是你站的地方，不是你。放弃你站过的地面。");
        A("herald.mob.leap.h", "구울은 떨어질 곳에 원을 먼저 띄우고 높이 뛴다. 원이 뜬 순간 네 할 일은 하나 — 원 밖으로.", "The ghoul marks a circle where it will land, then leaps high. The moment the circle appears, you have one task: be outside it.", "グールは着地点に円を浮かべてから高く跳ぶ。円が浮かんだ瞬間、お前のすることは一つ。円の外へ。", "食尸鬼先在落点显示圆圈，再高高跃起。圆圈出现的那一刻，你只需做一件事：出圈。");
        A("herald.mob.blink.h", "망령은 사라졌다가 표시한 곳에 나타나 영혼을 터뜨린다. 사라졌으면 표시를 찾아라. 표시 위에 서 있는 것만 피하면 된다.", "The wraith vanishes, then appears at a marked spot and bursts. When it fades, look for the mark. All you must avoid is standing on it.", "亡霊は消えてから印の場所に現れ、魂を弾けさせる。消えたら印を探せ。印の上に立たぬことだけ守ればいい。", "怨灵消失后会在标记处出现并引爆灵魂。它消失了，就找标记。只要别站在标记上就好。");
        A("herald.mob.xlaser.h", "임프의 광선은 네 자리에 X자로 엇갈려 떨어진다. 두 줄기 사이, 네 칸 중 하나로 반 걸음. 멀리 달아날 필요는 없다.", "The imp's laser crosses in an X on your position. Half a step into one of the four quarters between the two beams is enough. You needn't run far.", "インプの光線はお前の位置にX字で交わる。二本の間、四つの区画のどこかへ半歩。遠くへ逃げる必要はない。", "小恶魔的激光在你的位置交成X形。往两道光束之间的四格里任一格挪半步即可。不必跑远。");
        A("herald.mob.selfdestruct.h", "불꽃 해골은 가까이 오면 부풀어 오르다 터진다. 부풀기 시작했다면 아직 늦지 않다 — 그때 물러서면 된다. 가장 좋은 것은 멀리서 먼저 끄는 것.", "A flame skull swells as it nears you, then bursts. When it starts to swell, you are not yet too late; back off then. Better still, put it out from afar.", "炎のドクロは近づくと膨らみ、弾ける。膨らみ始めてもまだ遅くはない。その時退けばいい。最も良いのは、遠くから先に消すことだ。", "火焰骷髅靠近时会膨胀然后爆炸。开始膨胀时还不算晚，那时退开就行。最好的办法是远远地先解决它。");
        A("herald.mob.pounce.h", "지옥견은 달릴 길을 먼저 보여 준다. 그 길은 곧다 — 꺾지 않는다. 길의 옆에 서면 개는 지나간다.", "The hellhound shows its path before it runs, and that path is straight; it does not turn. Stand beside the line and the hound passes you by.", "ヘルハウンドは走る道を先に見せる。その道は真っ直ぐで、曲がらぬ。道の横に立てば犬は通り過ぎる。", "地狱犬在冲刺前会亮出路线，那条路是直的，不会转弯。站到线旁，犬就会从你身边掠过。");
        A("herald.mob.slam.h", "골렘의 파동은 셋, 점점 넓어진다. 첫 번째를 피했다고 끝이 아니다 — 둘째는 더 멀리, 셋째는 더 멀리. 골렘에게서 걸어서 벗어나라.", "The golem's shockwaves come three times, each wider than the last. Dodging the first is not the end; the second reaches farther, the third farther still. Walk away from the golem.", "ゴーレムの波動は三度、だんだん広がる。一度目を避けて終わりではない。二度目はより遠く、三度目はさらに遠く。ゴーレムから歩いて離れよ。", "魔像的冲击波有三次，一次比一次宽。躲过第一次不算完，第二次更远，第三次还要远。从魔像身边走开。");
        A("herald.mob.whirl.h", "악마 기사는 칼날을 휘감고 돌며 네 쪽으로 미끄러진다. 도는 동안 가까이 가지 마라. 미끄러짐이 끝나는 자리에서 베어라.", "The demon knight spins wrapped in blades and slides toward you. Don't close in while it spins. Strike where the slide ends.", "悪魔の騎士は刃をまとって回り、お前の方へ滑る。回っている間は近づくな。滑りが止まる所で斬れ。", "恶魔骑士裹着刀刃旋转，向你滑来。它转的时候别靠近。在它滑停的地方下手。");
        A("herald.mob.acid.h", "초원 슬라임이 남기는 웅덩이는 네 초 동안 아프다. 쓰러뜨렸다고 그 자리로 걸어 들어가지 마라 — 녹은 자리는 아직 녹아 있다.", "The puddle a meadow slime leaves burns for four seconds. Don't walk into the spot just because you killed it; the melted ground is still melting.", "草原スライムが残す水たまりは四秒間痛む。倒したからとその場へ歩み入るな。溶けた地はまだ溶けている。", "草原史莱姆留下的酸池会灼痛四秒。别因为杀了它就走进那里，融化的地面还在融化。");
        A("herald.mob.pollen.h", "거대 벌의 꽃가루 구름 안에서는 느려지고 조금씩 깎인다. 조금씩이 쌓여 네가 됐다. 구름은 뚫고 가는 것이 아니라 돌아가는 것이다.", "Inside the giant bee's pollen cloud you slow down and bleed a little at a time. A little at a time became all of you. A cloud is not to be crossed but gone around.", "巨大バチの花粉の雲の中では遅くなり、少しずつ削られる。少しずつが積もってお前になった。雲は突き抜けるものではなく、回り込むものだ。", "在巨型蜜蜂的花粉云里，你会变慢，还会一点点掉血。一点点累积成了你的结局。花粉云不是用来穿的，是用来绕的。");
        A("herald.mob.mines.h", "버섯 거인은 둘레에 버섯을 심고, 잠시 뒤 차례로 터뜨린다. 심는 것을 봤다면 그 둘레를 떠나라. 터지는 순서는 심은 순서다.", "The mushroom brute plants mushrooms around itself and sets them off one by one a moment later. If you saw it planting, leave that ground. They burst in the order they were planted.", "キノコの巨人は周りにキノコを植え、しばらくして順に爆発させる。植えるのを見たならその場を離れよ。弾ける順は植えた順だ。", "蘑菇巨人在周围种下蘑菇，片刻后依次引爆。看见它在种，就离开那一带。引爆的顺序就是种下的顺序。");
        A("herald.mob.howl.h", "다이어울프가 울부짖으면 둘레의 적이 잠시 빨라진다. 울음은 공격이 아니다 — 울음 뒤에 오는 것들이 공격이다. 울음을 들었으면 늑대부터 끊어라.", "When the dire wolf howls, the enemies around it quicken for a while. The howl is not the attack; what follows it is. Hear the howl, and cut the wolf first.", "ダイアウルフが遠吠えすれば、周りの敵がしばし速くなる。遠吠えは攻撃ではない。その後に来るものが攻撃だ。遠吠えを聞いたら、まず狼を断て。", "恐狼嚎叫时，周围的敌人会暂时加速。嚎叫不是攻击，嚎叫之后来的才是。听见嚎叫，先斩狼。");
        A("herald.mob.roots.h", "트렌트의 가시는 네 쪽으로 한 줄, 차례로 솟는다. 줄은 곧다. 줄의 끝에 서 있지 말고 줄의 옆에 서라.", "The treant's spikes rise toward you in a line, one after another. The line is straight. Don't stand at its end; stand beside it.", "トレントの棘はお前の方へ一列に、順に突き出る。列は真っ直ぐだ。列の先に立たず、列の横に立て。", "树人的根刺朝你排成一线依次冒出。那条线是直的。别站在线的尽头，站到线旁。");
        A("herald.mob.chain.h", "사슬 망령은 길을 보여 준 뒤 사슬을 던진다. 맞으면 끌려간다 — 그 앞 두 칸 반까지. 끌려간 뒤에도 틈은 있으니 숨을 놓지 마라.", "The chain wraith shows its path, then throws the chain. If it lands, it drags you to within two and a half tiles of it. Even then there is a gap left for you, so don't give up your breath.", "鎖の亡霊は道を見せてから鎖を投げる。当たれば引き寄せられる。奴の前、二マス半まで。引かれた後にも隙はある。息を手放すな。", "锁链怨灵先亮出路线再掷出锁链。被击中就会被拖到它面前两格半处。被拖过去之后仍有间隙，别松了那口气。");
        A("herald.mob.gaze.h", "공허 눈알은 부채꼴의 양 끝을 먼저 보여 주고, 그 사이를 광선으로 훑는다. 광선은 한 번만 스친다. 부채의 바깥으로 — 또는 눈알의 뒤로.", "The void eye shows both edges of a fan, then sweeps a beam between them. The beam grazes you only once. Get outside the fan, or behind the eye.", "虚無の目玉は扇の両端を先に見せ、その間を光線でなぎ払う。光線は一度しか掠めぬ。扇の外へ。あるいは目玉の後ろへ。", "虚空之眼先亮出扇形两端，再用光束扫过中间。光束只会扫到你一次。到扇形之外，或者绕到眼球背后。");
        A("herald.mob.reap.h", "영혼 수확자는 둘레를 두 번 벤다. 처음은 가까이, 두 번째는 그 바깥 고리. 첫 베기를 피해 물러섰다면 그 자리가 두 번째다 — 되레 안으로 들어가라.", "The soul reaper slashes around itself twice: first up close, then the ring beyond. If you stepped back from the first, you are standing in the second. Step in instead.", "魂の刈り手は周囲を二度斬る。初めは近く、二度目はその外の輪。一度目を避けて退いたなら、そこが二度目だ。むしろ内側へ入れ。", "灵魂收割者环身斩两次：先是近处，再是外圈。你为躲第一斩而后退，那正是第二斩落下的地方。反而要往里走。");
        A("herald.mob.fissure.h", "거상은 네 쪽으로 땅을 세 갈래로 가른다. 갈라진 금을 따라 가시가 차례로 솟는다. 갈래와 갈래 사이에 서라 — 금 위만 아니면 된다.", "The colossus splits the ground toward you in three lines, and spikes rise along each crack in turn. Stand between the lines; anywhere off the cracks will do.", "巨像はお前の方へ地面を三方向に裂く。裂け目に沿って棘が順に突き上がる。裂け目と裂け目の間に立て。裂け目の上でなければいい。", "巨像朝你把地面裂成三道，尖刺沿着裂缝依次升起。站在裂缝与裂缝之间，只要不在缝上就行。");
        A("herald.run.curse.h", "저주 제단의 값은 이 장이 끝날 때까지 간다 — 보스의 체력도 세 할 늘어난다는 뜻이다. 보상 다섯 할은 그 값이다. 받을 때 장의 끝까지 셈하라.", "The Cursed Altar's price runs to the end of the chapter, and that includes the boss, thirty percent heavier. Fifty percent more reward is what it buys. Count to the chapter's end before you accept.", "呪いの祭壇の代価はこの章が終わるまで続く。ボスの体力も三割増えるということだ。報酬五割はその代価だ。受ける時は章の終わりまで数えよ。", "诅咒祭坛的代价会持续到本章结束，这意味着首领的生命也多三成。多五成的奖励就是它的价钱。接受之前，先把这一章算到头。");
        A("herald.run.curse2.h", "저주를 받고 쓰러졌다. 저주는 준비 없는 자에게는 독, 준비된 자에게는 이자다. 앞 장을 여유 있게 넘긴 판에서만 받아라.", "You took the curse and fell. To the unready it is poison; to the prepared, interest. Accept it only in a run where the last chapter came easy.", "呪いを受けて倒れた。呪いは備えなき者には毒、備えた者には利息だ。前の章を余裕で越えたプレイでだけ受けよ。", "你接下诅咒，然后倒下。诅咒对没准备的人是毒，对准备好的人是利息。只在上一章轻松渡过的那局接受它。");
        A("herald.run.shop.h", "떠돌이 상점은 열다섯 초만 머문다. 코인을 쥐고 쓰러지는 것보다 어리석은 일은 없다 — 상점이 뜨면 가는 길에 적이 있어도 간다.", "The wandering shop stays only fifteen seconds. Nothing is more foolish than dying with coins in your hand. When the shop appears, you go, even through enemies.", "さすらいのショップは十五秒しかとどまらぬ。コインを握ったまま倒れるほど愚かなことはない。ショップが現れたら、道に敵がいても行け。", "流浪商店只停留十五秒。握着金币倒下是最蠢的事。商店一出现就去，哪怕路上有敌人。");
        A("herald.run.swarm.h", "영혼 부스러기 무리는 체력이 하나, 이빨은 없다. 그것들은 적이 아니라 수확이다. 무리가 오면 피하지 말고 가운데로 들어가라.", "The soul-mote swarm has one point of health and no teeth. They are not enemies; they are a harvest. When the swarm comes, don't dodge it. Walk into the middle.", "魂のくずの群れは体力が一、牙はない。あれは敵ではなく収穫だ。群れが来たら避けるな、真ん中へ入れ。", "灵魂碎屑群只有一点生命，没有牙。它们不是敌人，是收成。碎屑群来了别躲，走到中间去。");
        A("herald.run.tree.h", "영혼 조각을 쥐고 쓰러졌는가. 영혼 트리는 멈춘 시간 안에서 열린다 — 조각은 쌓아 두는 것이 아니라 바로 쓰는 것이다.", "Did you fall with Soul Shards unspent? The Soul Tree opens in stopped time. Shards are not for hoarding; spend them the moment you have them.", "魂のかけらを握ったまま倒れたか。魂のツリーは止まった時の中で開く。かけらは貯めるものではなく、すぐ使うものだ。", "你是攥着灵魂碎片倒下的吗？灵魂树在暂停的时间里开启。碎片不是攒的，是拿到就用的。");
        A("herald.run.laststand.h", "최후의 보루는 장마다 한 번, 체력이 삼 할 아래로 떨어질 때 스스로 깨어난다. 두 초의 무적과 밀어내는 빛. 그 두 초는 싸우라고 준 것이 아니다 — 빠져나오라고 준 것이다.", "The Last Stand wakes once a chapter, by itself, when your health drops under thirty percent: two seconds of invulnerability and a wave that throws everything back. Those two seconds were not given to fight with. They were given to get out.", "最後の砦は章ごとに一度、体力が三割を切った時にひとりでに目覚める。二秒の無敵と押し返す光。その二秒は戦うために与えられたのではない。抜け出すために与えられたのだ。", "最后的堡垒每章一次，在生命跌破三成时自行苏醒：两秒无敌，加一道推开一切的光。那两秒不是给你打的，是给你脱身的。");
        A("herald.run.laststand2", "보루는 이미 한 번 섰다. 두 번째 삼 할은 아무것도 지켜 주지 않았다. 보루가 섰다는 알림은 「이제부터 네 체력은 네 것뿐」이라는 말이다.", "The Stand had already risen once. The second time you dropped under thirty, nothing came. The notice that it fired means: from here on, your health is yours alone.", "砦はすでに一度立った。二度目の三割を守るものは何もなかった。砦が立ったという報せは、「ここからお前の体力はお前だけのもの」という意味だ。", "堡垒已经立过一次。第二次跌破三成时，没有任何东西来救你。堡垒触发的提示意味着：从此你的生命只能靠你自己。");
        A("herald.run.brand.h", "각인은 저울이다. 유리 대포로 네 할 더 때리고 세 할 덜 버티기로 했다면, 맞지 않는 쪽으로 싸워야 한다. 각인을 고르고 플레이를 바꾸지 않은 것 — 그것이 쓰러진 이유다.", "A brand is a scale. If Glass Cannon gave you forty percent more hitting and thirty percent less enduring, you must fight so as not to be hit. Choosing a brand without changing how you play — that is why you fell.", "刻印は天秤だ。ガラスの大砲で四割多く殴り、三割少なく耐えると決めたなら、当たらぬ戦い方をせねばならぬ。刻印を選んで戦い方を変えなかったこと。それが倒れた理由だ。", "烙印是一把秤。你选了玻璃大炮，多打四成、少挨三成，就得打一场不挨打的仗。选了烙印却没改打法，这就是你倒下的原因。");
        A("herald.run.brand2.h", "죽음의 춤을 새기고 쓰러졌다. 받는 피해가 반 배 더 — 그 각인은 「한 번도 맞지 않겠다」는 맹세다. 맹세를 지킬 수 없는 날에는 새기지 마라.", "You carved the Dance of Death and fell. Half again the damage taken: that brand is a vow never to be hit. On a day you cannot keep the vow, don't carve it.", "死の舞踏を刻んで倒れた。受けるダメージは半分増し。あの刻印は「一度も当たらぬ」という誓いだ。誓いを守れぬ日には刻むな。", "你刻下死亡之舞，然后倒下。受到的伤害多五成，那枚烙印是「一次也不挨打」的誓言。守不住誓言的日子，就别刻它。");
        A("herald.run.relic.h", "봉인된 석관은 2장부터 나타난다. 화살표를 따라가 곁에 머물면 봉인이 깨지고 유물이 나온다. 유물은 둘까지, 쿨타임은 한 배 반 — 둘째 유물은 첫째와 다른 때에 쓰는 것을 골라라.", "Sealed sarcophagi appear from Chapter 2. Follow the arrow and stay beside one, and the seal breaks for a relic. You may hold two, each with cooldowns half again as long, so choose a second that you will use at a different moment than the first.", "封印された石棺は二章から現れる。矢印をたどってそばにとどまれば封印が破れ、遺物が出る。遺物は二つまで、クールタイムは一倍半。二つ目は、一つ目と違う時に使うものを選べ。", "封印石棺从第2章起出现。跟着箭头守在旁边，封印就会破开掉出遗物。遗物最多两件，冷却是一倍半，所以第二件要选和第一件在不同时机用的。");
        A("herald.run.chest.h", "보물 상자는 셋 중 하나다. 체력이 닳았을 때의 「생명」은 가장 센 카드다 — 공격력 다섯 푼보다 지금 살아 있는 것이 먼저다.", "A treasure chest offers one of three. When your health is low, Life is the strongest card there is; being alive now comes before five percent more attack.", "宝箱は三つに一つ。体力が削れている時の「生命」は最も強いカードだ。攻撃力五分より、今生きていることが先だ。", "宝箱三选一。生命见底时，「生命」是最强的牌，先活着，再谈那5%攻击力。");
        A("herald.run.event.h", "이벤트는 셈이다. 습격은 상자, 황금 고블린은 코인, 제단은 조각. 셈이 맞지 않으면 버려라 — 이벤트를 놓쳐도 판은 계속되지만, 네가 쓰러지면 판은 끝난다.", "An event is a trade. The ambush pays a chest, the Golden Goblin coins, the altar shards. When the trade is bad, walk away: a missed event lets the run go on; a fallen hero ends it.", "イベントは勘定だ。襲撃は宝箱、黄金ゴブリンはコイン、祭壇はかけら。勘定が合わぬなら捨てよ。イベントを逃してもプレイは続くが、お前が倒れればプレイは終わる。", "事件是一场交易。伏击换宝箱，黄金哥布林换金币，祭坛换碎片。划不来就放手：错过事件，这一局还在；你倒下，这一局就完了。");
        A("herald.run.altar.h", "영혼 제단은 둘레에 머물라 한다 — 서 있으라는 말이 아니다. 원 안에서 걸어라. 원은 네가 생각하는 것보다 넓다.", "The Soul Altar asks you to stay within its circle, not to stand still. Keep walking inside it. The circle is wider than you think.", "魂の祭壇は輪の中にとどまれと言う。立ち止まれという意味ではない。輪の中で歩け。輪はお前が思うより広い。", "灵魂祭坛要你留在圈内，不是要你站着不动。在圈里走。圈比你想的大。");
        A("herald.run.levelup.h", "레벨업 배지가 켜진 채 쓰러졌다. 카드는 모아 둘 수 있지만, 모아 둔 카드는 죽은 네게 아무것도 아니다. 배지가 반짝이면 멈춰서 골라라 — 그 순간 시간도 멈춘다.", "You fell with the level-up badge still lit. Cards can be saved up, but saved cards mean nothing to the dead. When the badge blinks, stop and choose; time stops with you.", "レベルアップの印が灯ったまま倒れた。カードはためておけるが、ためたカードは死んだお前には何でもない。印が光ったら止まって選べ。その瞬間、時も止まる。", "你倒下时，升级徽章还亮着。卡牌可以攒，但攒下的卡对死人毫无意义。徽章一闪就停下来选，那一刻时间也会停。");
        A("herald.run.evo.h", "첫 보스를 넘기면 무기가 진화한다. 진화한 평타는 다른 무기다 — 사거리와 박자가 바뀐다. 2장의 첫 일 분은 새 무기를 배우는 시간으로 써라.", "Past the first boss, your weapon evolves, and an evolved attack is a different weapon: new reach, new rhythm. Spend the first minute of Chapter 2 learning it.", "最初のボスを越えれば武器が進化する。進化した通常攻撃は別の武器だ。射程も拍子も変わる。二章の最初の一分は、新しい武器を覚える時間に使え。", "过了第一个首领，武器就会进化。进化后的普攻是另一件武器，射程与节奏都变了。把第2章的第一分钟用来熟悉它。");
        A("herald.run.ult.h", "필살기 게이지가 가득 찬 채 쓰러졌다. 가득 찬 게이지는 쓰지 않은 목숨이다. 위험해지면 아껴 둘 것이 아니라 쏟을 것.", "You fell with your Ultimate gauge full. A full gauge is a life you didn't use. When things turn dangerous, it is not to be saved; it is to be spent.", "必殺技ゲージが満ちたまま倒れた。満ちたゲージは使わなかった命だ。危うくなったら、惜しむのではなく注げ。", "你倒下时必杀技充能是满的。满的充能就是一条没用的命。危险时不该省着，该倾泻出去。");
        A("herald.run.transcend.h", "레벨 쉰 — 더 오를 곳이 없다. 이제 경험치 막대 세 번마다 초월 카드가 온다. 막대는 네가 여전히 채우고 있는 것이다. 처치를 멈추지 마라.", "Level fifty: no higher to climb. From here, every third fill of the EXP bar brings a Transcendence card. The bar is still yours to fill. Don't stop killing.", "レベル五十。もう上はない。ここからは経験値バーが三度満ちるごとに超越のカードが来る。バーはまだお前が満たすものだ。撃破を止めるな。", "五十级，再无可升。从此经验条每满三次就来一张超越卡。那根条仍要靠你去填。别停下击杀。");
        A("herald.run.midboss.h", "중간 보스는 체력이 열두 배, 피해는 한 배 반. 쓰러뜨리면 특수 능력 포인트를 준다. 그러나 잡몹 사이에 섞여 오는 그것에 등을 보이지 마라 — 네 뒤에서 열두 배가 걸어오고 있었다.", "A mid-boss carries twelve times the health and half again the bite, and pays a special-ability point when it falls. But never turn your back on the one walking in among the crowd; twelvefold was coming up behind you.", "中ボスは体力が十二倍、ダメージは一倍半。倒せば特殊能力ポイントをくれる。だが雑兵に混じって来るそれに背を見せるな。お前の背後を十二倍が歩いていた。", "中头目生命十二倍，伤害一倍半，倒下时会给特殊能力点。可别对混在杂兵中走来的它转身，十二倍的东西正从你背后走来。");
        A("herald.sit.contact.meadow", "초원은 넓다. 넓은 곳에서 적의 몸에 닿았다는 것은 둘러싸였다는 뜻이다. 한쪽으로만 밀어라 — 등 뒤를 비워 두면 초원은 늘 길을 내준다.", "The meadow is wide. To be touched by an enemy in a wide place means you were surrounded. Push in one direction only; keep your back clear, and the meadow always opens a way.", "草原は広い。広い場所で敵の体に触れたということは、囲まれたということだ。一方向へだけ押せ。背後を空けておけば、草原はいつも道を開けてくれる。", "草原很宽。在宽阔之地被敌人碰到，说明你被包围了。只往一个方向推，留空身后，草原总会给你让路。");
        A("herald.sit.contact.cata", "묘역의 해골은 스킬이 없다. 곧장 달려올 뿐이다. 그래서 가장 많이 거둔다 — 숫자가 곧 스킬이다. 좁은 길에서 등을 돌리지 마라.", "The skeletons of the catacombs have no skills. They only run straight at you. That is why they reap the most: numbers are their skill. Never turn your back in a narrow way.", "墓所のスケルトンにスキルはない。ただ真っ直ぐ駆けてくるだけだ。だから最も多く刈り取る。数こそがスキルだ。狭い道で背を向けるな。", "墓穴的骷髅没有技能，只会直直冲来。所以它们收割得最多，数量就是它们的技能。在窄路上别转身。");
        A("herald.sit.contact.hell", "지옥의 적은 몸으로 온다 — 개는 달리고, 기사는 미끄러지고, 해골은 터진다. 지옥에서는 거리가 곧 체력이다.", "The enemies of Hell come with their bodies: the hound runs, the knight slides, the skull bursts. In Hell, distance is health.", "地獄の敵は体で来る。犬は走り、騎士は滑り、ドクロは弾ける。地獄では距離こそが体力だ。", "地狱的敌人靠身体压上来：犬奔跑，骑士滑行，骷髅爆炸。在地狱里，距离就是生命。");
        A("herald.sit.contact.abyss", "심연의 적은 너를 끌어당기고, 훑고, 둘레를 벤다. 심연에서 몸에 닿았다면 사슬이 먼저였을 것이다. 사슬이 그리는 길을 보라.", "The enemies of the abyss drag you, sweep you, and cut around themselves. If you were touched in the abyss, a chain came first. Watch the path the chain draws.", "深淵の敵はお前を引き寄せ、なぎ払い、周囲を斬る。深淵で体に触れたなら、先に鎖があったはずだ。鎖が描く道を見よ。", "深渊的敌人会拖你、扫你、环身而斩。在深渊里被碰到，多半是先中了锁链。看清锁链画出的路。");
        A("herald.sit.contact.endless", "무한의 사막에서는 모든 장의 적이 함께 온다. 묘역의 숫자와 지옥의 몸, 심연의 사슬이 한 화면에. 한 종류만 보지 마라.", "In the endless desert, the enemies of every chapter come together: the numbers of the catacombs, the bodies of Hell, the chains of the abyss on one screen. Don't watch only one kind.", "果てなき砂漠では、すべての章の敵が共に来る。墓所の数と地獄の体、深淵の鎖が一つの画面に。一種類だけを見るな。", "在无尽的沙漠里，各章的敌人一起来：墓穴的数量、地狱的身躯、深渊的锁链同在一屏。别只盯着一种。");
        A("herald.sit.boss.share.h", "보스 앞에서 쓰러졌다. 보스는 네 체력의 네 할을 넘겨 한 번에 가져가지 못한다 — 그러니 두 번은 맞은 것이다. 한 번은 배움이고, 두 번은 선택이다.", "You fell before a boss. No boss can take more than forty percent of your health in one blow, so you were struck at least twice. Once is a lesson. Twice is a choice.", "ボスの前で倒れた。ボスは一撃でお前の体力の四割を超えて奪えぬ。ゆえに二度は当たったのだ。一度は学び。二度は選択だ。", "你倒在首领面前。首领一击夺不走你四成以上的生命，所以你至少挨了两下。一下是教训，两下是选择。");
        A("herald.sit.boss.slime", "초원의 폭군은 네 첫 벽이다. 벽은 넘으라고 있는 것 — 그리고 넘은 뒤에는 무기가 바뀐다. 그 너머의 네 손은 지금과 다르다.", "The Tyrant of the Meadow is your first wall. Walls exist to be climbed, and past this one your weapon changes. The hands on the other side are not the hands you have now.", "草原の暴君はお前の最初の壁だ。壁は越えるためにある。そして越えた先では武器が変わる。その向こうのお前の手は、今の手とは違う。", "草原暴君是你的第一道墙。墙是用来翻的，翻过去之后，武器就会改变。墙那边的你的双手，已不是现在的双手。");
        A("herald.sit.boss.lich", "리치 왕은 가장 길게 싸우는 왕이다. 긴 싸움에서는 체력보다 집중이 먼저 닳는다. 그의 패턴은 하나하나 느리다 — 느린 것을 느리게 보라.", "The Lich King is the longest fight of all. In a long fight, focus wears out before health does. Each of his patterns is slow; look at slow things slowly.", "リッチ王は最も長く戦う王だ。長い戦いでは体力より先に集中が削れる。奴の型は一つ一つが遅い。遅いものは遅く見よ。", "巫妖王是打得最久的王。打得久，先耗尽的不是生命而是专注。他的招式一个个都慢，慢的东西就慢慢看。");
        A("herald.sit.boss.demon", "지옥의 군주는 세 번 바뀐다. 처음은 땅, 다음은 하늘, 마지막은 좁아지는 땅. 네가 쓰러진 단계가 네가 다음에 배울 단계다.", "The Demon Lord changes three times: first the ground, then the sky, then the ground closing in. The phase you fell in is the phase you will learn next.", "地獄の君主は三度変わる。初めは地、次は空、最後は狭まる地。お前が倒れた段階が、お前が次に学ぶ段階だ。", "地狱领主会变三次：先是地面，再是天空，最后是不断收窄的地面。你倒下的那个阶段，就是你下次要学的阶段。");
        A("herald.sit.boss.mirror", "거울의 군주는 네가 쓰러뜨린 모든 것의 메아리다. 그를 상대하는 법은 하나다 — 너라면 어떻게 피하겠는가. 그것을 하면 된다.", "The Mirror Sovereign is the echo of everything you have slain. There is one way to face him: ask how you would dodge yourself, and do that.", "鏡の君主はお前が倒したすべての残響だ。奴と向き合う術は一つ。お前ならどう避けるか。それをすればいい。", "镜之君主是你所击败一切的回响。对付他只有一个法子：想想你会怎么躲自己，然后照做。");
        A("herald.sit.barrier.h", "결계 안에서 쓰러졌다. 결계는 벽이 아니라 시간이다 — 열다섯 초, 킹 슬라임은 아홉 초. 이기려 하지 말고 살아 넘겨라. 결계가 깨지면 다시 네 차례다.", "You fell inside the barrier. A barrier is not a wall but a span of time: fifteen seconds, nine for King Slime. Don't try to win it; outlive it. When it shatters, the turn is yours again.", "結界の中で倒れた。結界は壁ではなく時間だ。十五秒、キングスライムなら九秒。勝とうとせず、生きて越えよ。結界が砕ければ、再びお前の番だ。", "你倒在结界之中。结界不是墙，是一段时间：十五秒，史莱姆王是九秒。别想赢它，活过去就好。结界碎了，又轮到你。");
        A("herald.sit.lowhp.h", "체력 한 줌으로 보스를 넘기고, 다음 장의 첫 적에게 쓰러졌다. 문 앞의 서른 초는 쉬는 시간이다 — 고기 · 코인 · 영혼 트리. 보스를 넘긴 손으로 곧장 다음 문을 열지 마라.", "You passed the boss with a handful of health, and fell to the first enemy of the next chapter. The thirty seconds before the gate are for resting: meat, coins, the Soul Tree. Don't open the next door with the same hands that just finished the boss.", "体力ひと握りでボスを越え、次の章の最初の敵に倒れた。門の前の三十秒は休む時間だ。肉、コイン、魂のツリー。ボスを越えたその手で、すぐ次の門を開けるな。", "你靠一点点生命撑过首领，却倒在下一章的第一个敌人手里。门前的三十秒是用来休整的：肉、金币、灵魂树。别用刚打完首领的那双手直接推开下一扇门。");
        A("herald.sit.lowhp2", "장과 장 사이에서 네 체력은 저절로 돌아오지 않는다. 보스가 쓰러진 자리에 남은 고기와 코인을 다 거둔 뒤에 문을 넘어라. 문은 서른 초를 기다려 준다.", "Between chapters, your health does not come back on its own. Gather every scrap of meat and coin left where the boss fell before you cross the gate. The gate waits thirty seconds.", "章と章の間で、お前の体力はひとりでに戻らぬ。ボスが倒れた場所に残った肉とコインをすべて拾ってから門を越えよ。門は三十秒待ってくれる。", "章与章之间，你的生命不会自己回来。把首领倒下处剩下的肉和金币捡完，再过门。门会等你三十秒。");
        A("herald.sit.dev.h", "개발자. 거울의 군주의 몸을 빌려 모든 영웅의 마지막 필살기를 돌려 쓴다. 하나가 뜰 때마다 알림이 어느 영웅의 것인지 말해 준다 — 알림을 읽는 자가 산다.", "The Developer: wearing the Mirror Sovereign's body, cycling through the final Ultimate of every hero. Each time one comes, a notice names whose it is. Those who read the notice live.", "開発者。鏡の君主の体を借り、すべての英雄の最終必殺技を順に使う。一つ来るたびに、報せがどの英雄のものか告げる。報せを読む者が生き残る。", "开发者，借着镜之君主的身体，轮番使出所有英雄的最终必杀技。每来一招，提示都会说明那是哪位英雄的。读提示的人才活得下来。");
        A("herald.sit.dev2", "개발자를 만났다는 것은 열다섯 분을 버티고, 깨어난 왕들을 모두 다시 눕혔다는 것이다. 여기서 쓰러진 것은 패배가 아니라 기록이다.", "To have met the Developer means you lasted fifteen minutes and laid every awakened king down again. To fall here is not a defeat. It is a record.", "開発者に出会ったということは、十五分耐え、目覚めた王たちをすべて再び寝かせたということだ。ここで倒れたのは敗北ではない。記録だ。", "遇见开发者，意味着你撑过了十五分钟，把苏醒的王全都再度放倒。倒在这里不是失败，是纪录。");
        A("herald.sit.mom.h", "그녀가 강림했다. 개발자의 두 배 — 체력도, 피해도, 걸음도. 필살기는 처음엔 다섯 초마다, 체력이 닳을수록 한 초까지 빨라진다. 그녀의 끝은 네 끝보다 빨리 온다. 그것만 믿고 버텨라.", "She has descended, twice the Developer in health, in damage, in stride. Her Ultimate comes every five seconds at first, quickening to every second as she weakens. Her end comes faster than yours does. Hold on to that and endure.", "彼女が降臨した。開発者の二倍。体力も、ダメージも、歩みも。必殺技は初めは五秒ごと、体力が削れるほど一秒まで速まる。彼女の終わりはお前の終わりより早く来る。それだけを信じて耐えよ。", "她降临了。开发者的两倍：生命、伤害、步伐皆是。必杀技起初每五秒一次，随着生命削减快到每秒一次。她的终点比你的来得更早。只信这一点，撑下去。");
        A("herald.sit.mom2", "개발자 엄마 앞에서 쓰러졌다. 이 자리까지 온 자는 많지 않다. 여기부터는 전령이 네게 가르칠 것이 없다 — 네가 전령에게 가르칠 차례다.", "You fell before the Developer's Mom. Few have come this far. From here the Herald has nothing left to teach you; it is your turn to teach the Herald.", "開発者のママの前で倒れた。ここまで来た者は多くない。ここからは使者がお前に教えることはない。お前が使者に教える番だ。", "你倒在开发者的妈妈面前。能走到这里的人不多。从这里起使者再没什么能教你，该你来教使者了。");
        A("herald.sit.midboss", "중간 보스에게 쓰러졌다. 그것은 잡몹처럼 걸어와 보스처럼 때린다. 체력바 위의 표시를 보았는가 — 표시가 붙은 것은 잡몹이 아니다.", "A mid-boss brought you down. It walks like a minion and hits like a boss. Did you see the mark above its health bar? What carries that mark is no minion.", "中ボスに倒された。それは雑兵のように歩き、ボスのように殴る。体力バーの上の印を見たか。印の付いたものは雑兵ではない。", "你被中头目放倒了。它像杂兵一样走来，像首领一样出手。看见它生命条上方的标记了吗？带着那个标记的，不是杂兵。");
        A("herald.sit.event.fail", "이벤트가 끝나기 전에 네가 끝났다. 습격은 둘레에서 한꺼번에 온다 — 가운데가 아니라 한쪽 끝에서 받아라. 둘레를 선으로 바꾸는 것이 습격을 사는 법이다.", "You ended before the event did. An ambush comes from every side at once; meet it at one edge, not in the middle. Turning a circle into a line is how you survive an ambush.", "イベントが終わる前にお前が終わった。襲撃は周囲から一斉に来る。真ん中ではなく、一方の端で受けよ。輪を線に変えることが、襲撃を生き抜く術だ。", "事件还没结束，你先结束了。伏击从四面一齐压来，要在一侧边缘迎战，而不是在中央。把一个圈变成一条线，这就是活过伏击的办法。");
        A("herald.sit.goblin", "황금 고블린을 쫓다 쓰러졌다. 스무 초 안에 잡으면 코인이 쏟아진다 — 그러나 고블린은 늘 적 사이로 달아난다. 코인은 다음 상점에서도 벌 수 있고, 목숨은 그렇지 않다.", "You fell chasing the Golden Goblin. Catch it within twenty seconds and coins pour out, but the goblin always flees through the enemy. Coins can be earned at the next shop. A life cannot.", "黄金ゴブリンを追って倒れた。二十秒以内に捕まえればコインがあふれる。だがゴブリンはいつも敵の間へ逃げる。コインは次のショップでも稼げるが、命はそうではない。", "你追着黄金哥布林倒下了。二十秒内抓住它金币就会倾泻，可哥布林总往敌群里逃。金币下个商店还能挣，命不能。");
        A("herald.prog.ch1", "1장에서 쓰러졌다. 이 장은 가르치는 장이다 — 적은 느리고, 레벨은 빨리 오른다. 여기서의 죽음은 힘이 모자란 것이 아니라 길을 잘못 든 것이다.", "You fell in Chapter 1. This chapter is a teacher: the enemies are slow and the levels come quickly. A death here is not a lack of strength. It is a wrong turn.", "一章で倒れた。この章は教える章だ。敵は遅く、レベルは早く上がる。ここでの死は力不足ではなく、道の間違いだ。", "你倒在第1章。这一章是来教你的：敌人慢，升级快。死在这里不是力量不够，是走错了路。");
        A("herald.prog.ch1b.h", "1장의 세 분은 바쁜 세 분이어야 한다. 상점은 여든 마리쯤마다 오고, 부스러기는 스물다섯 초마다 온다. 둘 다 놓치지 않은 자가 2장을 산다.", "The three minutes of Chapter 1 should be busy minutes. The shop comes every eighty kills or so, the motes every twenty-five seconds. Whoever misses neither survives Chapter 2.", "一章の三分は忙しい三分でなければならぬ。ショップは八十体ほどごとに、くずは二十五秒ごとに来る。どちらも逃さぬ者が二章を生き抜く。", "第1章的三分钟应当是忙碌的三分钟。商店约每八十个击杀来一次，碎屑每二十五秒来一次。两者都不错过的人，才活得过第2章。");
        A("herald.prog.ch2", "2장. 많은 이가 여기서 쓰러진다. 1장의 느린 적에 익은 손이 2장의 속도를 따라가지 못한다. 2장은 1장의 두 배가 아니다 — 다른 장이다. 첫 일 분은 물러서며 싸워라.", "Chapter 2. Many fall here. Hands grown used to the slow enemies of Chapter 1 cannot keep up with the pace of 2. Chapter 2 is not twice Chapter 1; it is a different chapter. Fight the first minute while backing away.", "二章。多くの者がここで倒れる。一章の遅い敵に慣れた手が、二章の速さに追いつけぬ。二章は一章の二倍ではない。別の章だ。最初の一分は退きながら戦え。", "第2章。很多人倒在这里。习惯了第1章慢敌人的手，跟不上第2章的速度。第2章不是第1章的两倍，是另一章。头一分钟边退边打。");
        A("herald.prog.ch2b.h", "2장에서 쓰러진 것은 네 탓이 아니다. 네 영웅의 성장이 아직 2장을 못 따라간 것이다. 1장에서 상점을 지나쳤는가, 영혼 트리를 비워 두었는가 — 2장은 1장에서 정해진다.", "Falling in Chapter 2 is not your fault; your hero's growth has not yet caught up with it. Did you pass the shop in Chapter 1? Leave the Soul Tree bare? Chapter 2 is decided in Chapter 1.", "二章で倒れたのはお前のせいではない。英雄の成長がまだ二章に追いついていないのだ。一章でショップを通り過ぎたか、魂のツリーを空けておいたか。二章は一章で決まる。", "倒在第2章不是你的错，是你的英雄还没成长到第2章。第1章你路过了商店吗？灵魂树空着吗？第2章是在第1章决定的。");
        A("herald.prog.ch3", "3장. 불타는 지옥은 세 번 바뀌는 군주와 몸으로 오는 적들의 장이다. 여기까지 왔으면 각인이 둘, 유물이 하나는 있어야 한다. 비어 있다면 2장을 서둘러 넘긴 것이다.", "Chapter 3. The Burning Hell belongs to a lord who changes three times and to enemies who come with their bodies. By now you should carry two brands and one relic. If you carry none, you hurried through Chapter 2.", "三章。燃える地獄は三度変わる君主と、体で来る敵たちの章だ。ここまで来たなら刻印は二つ、遺物は一つあるはずだ。空なら、二章を急いで越えたのだ。", "第3章。燃烧地狱属于会变三次的领主，和靠身躯压来的敌人。走到这里，你该有两枚烙印、一件遗物。若两手空空，说明第2章你走得太急。");
        A("herald.prog.ch4", "4장. 심연은 네가 쌓아 온 것을 되비친다. 레벨은 멈추고 초월만 남는 장 — 여기서 쓰러진 자는 약한 자가 아니다. 끝에서 두 걸음 앞에 선 자다.", "Chapter 4. The abyss reflects everything you have built. Levels stop here and only Transcendence remains. Whoever falls here is not weak. They stood two steps from the end.", "四章。深淵はお前が積み上げたものを映し返す。レベルは止まり、超越だけが残る章。ここで倒れた者は弱い者ではない。終わりの二歩手前に立った者だ。", "第4章。深渊映照你积累的一切。等级在此停下，只剩超越。倒在这里的人不是弱者，是站在终点两步之前的人。");
        A("herald.prog.e.first.h", "무한의 첫 보스는 네 분에 온다. 그 뒤로는 쓰러뜨릴 때마다 다음 왕이 더 빨리 일어선다. 네 분은 준비 시간이다 — 레벨 열에서 시작한 몸을 그 안에 키워라.", "The first boss of Endless comes at four minutes. After that, each king you fell brings the next one faster. Those four minutes are for preparation: grow the body that started at level ten before they end.", "エンドレスの最初のボスは四分で来る。その後は倒すたびに次の王がより早く立ち上がる。四分は備えの時間だ。レベル十で始まった体を、その内に育てよ。", "无尽的第一个首领在第四分钟到来。之后每放倒一个，下一个王就起得更快。那四分钟是准备时间，把从十级起步的身体在这段时间里养起来。");
        A("herald.prog.e.ease.h", "무한 다섯 분을 넘겼다. 완화는 아홉 분에 끝난다 — 적의 체력과 이빨이 제값으로 돌아온다. 다섯에서 아홉 사이의 네 분이 진짜 무한의 문턱이다.", "You passed five minutes of Endless. The mercy ends at nine, when enemy health and bite return to full price. The four minutes between five and nine are the true threshold of Endless.", "エンドレスの五分を越えた。緩和は九分で終わる。敵の体力と牙が元の値に戻る。五分から九分の四分間が、真のエンドレスの敷居だ。", "你撑过了无尽的五分钟。宽限在第九分钟结束，敌人的生命与咬合力回到原价。五到九之间的四分钟，才是无尽真正的门槛。");
        // 1.4.2~ 최후의 시간 왕 두 무리 · 무한 레벨 곡선 (무한 30분 기획 B1 · A1)
        A("herald.prog.e.ten", "열 분을 넘겼다. 왕들은 쓰러뜨릴 때마다 더 빨리 돌아온다. 열다섯 분이면 왕들이 깨어난다 — 둘이 먼저, 나머지 둘은 그 둘이 눕거나 일 분 뒤에. 레벨이 더디다고 서두르지 마라. 너는 끝까지 자란다.", "You passed ten minutes. The kings return faster each time they fall. At fifteen the kings wake: two first, the other two when those lie down or a minute has passed. Do not rush because your levels come slowly. You grow until the very end.", "十分を越えた。王たちは倒すたびに早く戻る。十五分で王たちが目覚める。まず二体、残る二体はその二体が倒れるか一分後に。レベルの歩みが遅いと急くな。お前は最後まで育つ。", "你撑过了十分钟。王每倒下一次就回来得更快。十五分钟时诸王苏醒：先是两个，另外两个在前两个倒下或一分钟后醒来。别因升级变慢而着急，你会一直成长到最后。");
        A("herald.prog.e.final", "열다섯 분 — 최후의 시간. 왕들이 둘씩 깨어나고, 모두 눕으면 개발자가 내려온다. 여기서 쓰러진 것은 이미 순위표에 적힌 죽음이다.", "Fifteen minutes: the final hour. The kings wake two by two, and when all of them lie down, the Developer descends. A death here is already written on the leaderboard.", "十五分。最後の時。王たちは二体ずつ目覚め、皆が横たわれば開発者が降りてくる。ここでの死は、すでにランキングに記された死だ。", "十五分钟，最后时刻。诸王两两苏醒，当他们全部倒下，开发者便会降临。死在这里的死，早已写在排行榜上。");
        A("herald.prog.e.beyond", "한계 돌파. 클리어 뒤의 시간은 셈이 아니라 자랑이다. 여기까지였군 — 그것으로 충분하다.", "Beyond the limit. Time after the clear is not a count but a boast. So this is where it ended. That is enough.", "限界突破。クリア後の時間は勘定ではなく誇りだ。ここまでだったか。それで十分だ。", "突破极限。通关之后的时间不是计数，是炫耀。到此为止了啊。这就够了。");
        A("herald.prog.giveup", "여기까지. 포기는 죽음이 아니다 — 버틴 시간이 남고, 순위표에 오른다. 전령은 포기한 자에게 할 말이 없다. 다음에 보자.", "So far, then. Giving up is not dying: the time you lasted remains, and it goes on the board. The Herald has nothing to say to one who chose to stop. Until next time.", "ここまでか。ギブアップは死ではない。耐えた時間が残り、ランキングに載る。使者は自ら止めた者に言うことはない。また次に。", "到此为止。放弃不是死亡，撑过的时间会留下，并登上排行榜。使者对主动停下的人无话可说。下次见。");
        A("herald.prog.giveup2", "결과를 보러 가는 길. 버틴 시간과 눕힌 왕의 수가 남는다. 그것은 전령도 지우지 못한다.", "On the way to the results. What remains is the time you lasted and the kings you laid down. Not even the Herald can erase that.", "結果を見に行く道。耐えた時間と寝かせた王の数が残る。それは使者にも消せぬ。", "去看结果的路上。留下的是你撑过的时间和放倒的王的数目。那是连使者也抹不掉的。");
        A("herald.count.first", "처음 쓰러졌다. 이 세계는 죽음을 세지 않는다 — 다시 선 횟수를 센다. 포인트는 남고, 계약은 남고, 네가 본 것은 남는다.", "Your first fall. This world does not count deaths; it counts the times you stood again. The points remain, the contracts remain, and what you saw remains.", "初めて倒れた。この世界は死を数えぬ。再び立った回数を数える。ポイントは残り、契約は残り、お前が見たものは残る。", "你第一次倒下。这个世界不数死亡，只数你重新站起的次数。点数留着，契约留着，你看见的也留着。");
        A("herald.count.first2", "첫 죽음. 모든 영웅이 한 번은 여기 선다. 거울의 군주조차 네가 쓰러뜨린 것들의 메아리로 만들어졌다 — 쓰러진 것 또한 메아리가 된다.", "The first death. Every hero stands here once. Even the Mirror Sovereign was made from the echoes of what you slew, and what falls becomes an echo, too.", "最初の死。すべての英雄が一度はここに立つ。鏡の君主すら、お前が倒したものの残響から作られた。倒れたものもまた、残響になる。", "第一次死亡。每位英雄都会在这里站一次。连镜之君主也是由你击败之物的回响造就，倒下的东西，同样会成为回响。");
        A("herald.count.first3", "두려워할 것 없다. 결과 화면에 적힌 것 중 사라지는 것은 하나도 없다. 「다시 하기」— 그 버튼이 이 세계의 심장이다.", "There is nothing to fear. Nothing written on the result screen is lost. Retry: that button is the heart of this world.", "恐れることはない。結果画面に記されたもので消えるものは一つもない。「もう一度」。そのボタンがこの世界の心臓だ。", "不必害怕。结果画面上写下的东西，没有一样会消失。「再来一次」，那个按钮就是这个世界的心脏。");
        A("herald.count.streak3", "같은 영웅, 같은 난이도, 세 번. 벽은 정면으로 밀어서만 넘는 것이 아니다. 다른 손, 다른 난이도 — 계약과 숙련과 기억은 어디서든 오른다.", "Same hero, same difficulty, three times. A wall is not only climbed head-on. Another hand, another difficulty: contracts, mastery and memories rise wherever you go.", "同じ英雄、同じ難易度、三度。壁は正面から押すだけで越えるものではない。別の手、別の難易度。契約も熟練も記憶も、どこにいても積み上がる。", "同一位英雄，同一难度，三次。墙不只靠正面硬推才能翻过。换一只手，换一个难度，契约、熟练与记忆在哪里都会累积。");
        A("herald.count.streak3b.h", "세 번 같은 자리. 세 번째 죽음이 첫 번째와 같은 원인이라면 바뀐 것은 하나도 없다. 결과 화면의 「쓰러진 곳」 줄을 읽어라 — 그것이 전령이 네게 남기는 숙제다.", "Three times in the same place. If the third death had the same cause as the first, nothing has changed. Read the \"Fell to\" line on the result screen. That is the homework the Herald leaves you.", "三度、同じ場所。三度目の死が一度目と同じ原因なら、何一つ変わっていない。結果画面の「倒れた原因」の行を読め。それが使者がお前に残す宿題だ。", "三次倒在同一处。若第三次死因与第一次相同，就什么都没变。读一读结果画面上「倒下于」那一行，那是使者留给你的作业。");
        A("herald.count.streak3c.h", "세 번. 난이도를 한 칸 내리는 것은 물러서는 것이 아니다. 보통에서 무한이 열리고, 쉬움에서 일일 도전이 열린다. 길은 하나가 아니다.", "Three times. Stepping down one difficulty is not retreat. Normal opens Endless; Easy opens the Daily Challenge. There is more than one road.", "三度。難易度を一段下げるのは退くことではない。ノーマルでエンドレスが開き、イージーでデイリーチャレンジが開く。道は一つではない。", "三次。把难度降一档不是退缩。普通开启无尽，简单开启每日挑战。路不止一条。");
        A("herald.count.ch5.1", "이 장에서 다섯 번째. 1장이 다섯 번 너를 눕혔다면 영웅을 바꿔 보라. 총은 멀리서, 검은 가까이서 — 같은 장이 다른 장이 된다.", "Your fifth fall in this chapter. If Chapter 1 has laid you down five times, try another hero. A gun from afar, a sword up close: the same chapter becomes a different one.", "この章で五度目。一章が五度お前を寝かせたなら、英雄を変えてみよ。銃は遠くから、剣は近くから。同じ章が別の章になる。", "你在这一章第五次倒下。若第1章放倒了你五次，就换个英雄试试。枪在远处，剑在近处，同一章会变成另一章。");
        A("herald.count.ch5.2", "2장에서 다섯 번째. 2장은 이 세계가 가장 많이 거두는 장이다. 다섯 번은 부끄러운 수가 아니다 — 다섯 번 2장을 본 자는 2장을 안다. 이번에는 리치 왕의 등불까지 보게 될 것이다.", "Your fifth fall in Chapter 2. Chapter 2 is where this world reaps the most. Five is no shameful number; whoever has seen Chapter 2 five times knows Chapter 2. This time you will see as far as the Lich King's lanterns.", "二章で五度目。二章はこの世界が最も多く刈り取る章だ。五度は恥じる数ではない。五度二章を見た者は二章を知っている。今度はリッチ王の灯籠まで見ることになるだろう。", "你在第2章第五次倒下。第2章是这个世界收割最多的一章。五次不是可耻的数字，看过第2章五次的人，就懂第2章。这一次，你会看到巫妖王的灯。");
        A("herald.count.ch5.3", "3장에서 다섯 번째. 지옥을 다섯 번 보았다. 군주의 세 단계 중 어디서 쓰러졌는지 세어 보라 — 다섯 번이 모두 같은 단계라면, 그 단계만 연습하면 된다.", "Your fifth fall in Chapter 3. You have seen Hell five times. Count which of the lord's three phases you fell in. If all five were the same phase, that phase is all you need to practice.", "三章で五度目。地獄を五度見た。君主の三段階のどこで倒れたか数えてみよ。五度がすべて同じ段階なら、その段階だけを練習すればいい。", "你在第3章第五次倒下。地狱你看了五回。数数你倒在领主三个阶段中的哪一个。若五次都在同一阶段，那就只需练那一阶段。");
        A("herald.count.ch5.4", "4장에서 다섯 번째. 심연은 다섯 번 너를 되비췄다. 거울은 네가 가장 많이 쓴 것을 돌려준다 — 다섯 번 같은 것을 썼는가. 이번에는 다른 것을 많이 써 보라.", "Your fifth fall in Chapter 4. The abyss has reflected you five times. The mirror returns whatever you used most. Did you use the same thing five times? This time, lean on something else.", "四章で五度目。深淵は五度お前を映し返した。鏡はお前が最も使ったものを返す。五度同じものを使ったか。今度は別のものを多く使ってみよ。", "你在第4章第五次倒下。深渊映照了你五次。镜子会把你用得最多的还回来。五次都用了同样的东西吗？这次多用点别的。");
        A("herald.count.afterclear", "클리어한 자가 다시 쓰러졌다. 세상을 한 번 구한 손도 넘어진다. 이것은 뒷걸음이 아니다 — 끝을 본 자만이 가질 수 있는 죽음이다.", "One who cleared has fallen again. Even hands that saved the world once can stumble. This is not a step backward. It is a death only those who have seen the end can have.", "クリアした者が再び倒れた。一度世界を救った手も躓く。これは後退ではない。終わりを見た者だけが持てる死だ。", "通关过的人又倒下了。救过世界一次的手也会跌倒。这不是倒退，是只有见过结局的人才配拥有的死亡。");
        A("herald.count.afterclear2", "엔딩을 본 뒤의 죽음은 무게가 다르다. 네가 잃은 것은 없다 — 다음 난이도가, 무한이 이미 열려 있다. 이제 죽음은 값이 아니라 연습이다.", "A death after the ending weighs differently. You have lost nothing; the next difficulty and Endless are already open. From now on, death is not a price. It is practice.", "エンディングを見た後の死は重みが違う。お前が失ったものはない。次の難易度も、エンドレスもすでに開いている。もう死は代価ではなく、練習だ。", "看过结局之后的死，分量不同。你没有失去什么，下一难度与无尽都已开启。从现在起，死亡不是代价，是练习。");
        A("herald.hero.gunner.1", "마지막 총잡이가 쓰러졌다. 탄창은 비었는가.\n“…아니. 한 발 남았다. 다음 판에 쓴다.”", "The last gunslinger has fallen. Is the magazine empty?\n\"...No. One round left. I'll spend it next run.\"", "最後のガンマンが倒れた。弾倉は空か。\n「……いや。一発残ってる。次のプレイで使う。」", "最后的枪手倒下了。弹匣空了吗？\n“……没有。还剩一发。下一局用。”");
        A("herald.hero.gunner.2", "마을의 마지막 총잡이. 네가 쓰러지면 마을은 누가 지키는가.\n“그래서 다시 가는 거다.”", "The last gunslinger of the village. If you fall, who guards the village?\n\"That's why I'm going back.\"", "村の最後のガンマン。お前が倒れたら村は誰が守る。\n「だからまた行くんだ。」", "村里最后的枪手。你倒下了，村子谁来守？\n“所以我才要再去。”");
        A("herald.hero.gunner.3", "총알은 떨어진다. 떨어진 뒤의 너는 무엇인가.\n“재장전하는 놈이지.”", "Bullets run out. What are you, once they have?\n\"The guy who reloads.\"", "弾は尽きる。尽きた後のお前は何だ。\n「リロードする奴さ。」", "子弹会打光。打光之后的你是什么？\n“负责装填的那个家伙。”");
        A("herald.hero.gunner.4", "모자 띠에 꽂을 탄피가 아직 없다.\n“마지막 탄피는 마지막에 줍는다. 아직이다.”", "There is still no casing to tuck into your hatband.\n\"The last casing gets picked up last. Not yet.\"", "帽子のバンドに差す薬莢がまだない。\n「最後の薬莢は最後に拾う。まだだ。」", "帽带上还没有可插的弹壳。\n“最后一枚弹壳要最后捡。还没到。”");
        A("herald.hero.gunner.5", "왕 앞에서 총잡이가 쓰러졌다. 멀리서 쏘는 자가 왜 가까이 있었나.\n“…조준이 길었다. 다음엔 짧게.”", "The gunslinger fell before a king. Why was one who shoots from afar standing so close?\n\"...I aimed too long. Shorter next time.\"", "王の前でガンマンが倒れた。遠くから撃つ者がなぜ近くにいた。\n「……狙いが長かった。次は短く。」", "枪手倒在王面前。远远开枪的人，为什么会在那么近？\n“……瞄得太久了。下次短一点。”");
        A("herald.hero.gunner.6", "세상을 구할 총잡이. 거울이 네 총을 되비췼다.\n“내 총보다 빠른 놈은 없다. 거울이라도.”", "The gunslinger who would save the world. The mirror reflected your gun.\n\"Nobody's faster than my gun. Not even a mirror.\"", "世界を救うはずのガンマン。鏡がお前の銃を映し返した。\n「俺の銃より速い奴はいない。鏡だろうとな。」", "本该拯救世界的枪手。镜子映出了你的枪。\n“没人比我的枪快。镜子也不行。”");
        A("herald.hero.sword.1", "칼날은 떨어지지 않는다고 했다. 떨어진 것은 기사였다.\n“칼은 아직 손에 있다. 그러면 된다.”", "You said a blade never runs out. It was the knight who fell.\n\"The sword is still in my hand. That is enough.\"", "刃は尽きぬと言った。尽きたのは騎士の方だった。\n「剣はまだ手にある。それでいい。」", "你说刀刃永不会用尽。倒下的，却是骑士。\n“剑还在手里。那就够了。”");
        A("herald.hero.sword.2", "녹슨 장검 한 자루로 어디까지 가려 하는가.\n“녹은 벗겨진다. 휘두를수록.”", "How far do you mean to go with one rusty longsword?\n\"Rust comes off. The more you swing.\"", "錆びた長剣一本でどこまで行くつもりだ。\n「錆は落ちる。振るうほどに。」", "凭一把生锈的长剑，你想走多远？\n“锈会掉的。越挥越少。”");
        A("herald.hero.sword.3", "검은 가깝다. 가까운 것은 맞는다.\n“휘두르는 동안은 반만 맞는다. 쉬지 않으면 된다.”", "A sword is close, and what is close gets hit.\n\"Half as hard while I'm swinging. So I don't stop swinging.\"", "剣は近い。近いものは当たる。\n「振るっている間は半分しか当たらぬ。休まねばいい。」", "剑很近。近的东西会挨打。\n“挥剑时只挨一半。不停手就行。”");
        A("herald.hero.sword.4", "떠돌이는 지킬 것이 없는 자를 부르는 말이다.\n“그래서 전부를 지킨다.”", "\"Wanderer\" is a word for one with nothing to protect.\n\"So I protect everything.\"", "さすらいとは、守るものなき者を呼ぶ言葉だ。\n「だから全部を守る。」", "「流浪」是用来称呼无所守护之人的词。\n“所以我守护一切。”");
        A("herald.hero.sword.5", "둘러싸였다. 검은 사방을 베지만 한 번에 한 방향이다.\n“회전 베기를 아꼈다. 다음엔 아끼지 않는다.”", "You were surrounded. A sword cuts every direction, but one at a time.\n\"I held back the Spin Slash. Next time I won't.\"", "囲まれた。剣は四方を斬るが、一度に一方向だ。\n「回転斬りを惜しんだ。次は惜しまぬ。」", "你被包围了。剑能斩向四方，可一次只有一个方向。\n“我省着回旋斩没用。下次不省了。”");
        A("herald.hero.sword.6", "거울이 네 검을 들었다. 네 검은 느리다 — 네가 가장 잘 안다.\n“느린 검은 피하기도 쉽지. 그것도 내가 가장 잘 알고.”", "The mirror took up your sword. Your sword is slow; you know that best.\n\"A slow sword is easy to dodge. I know that best, too.\"", "鏡がお前の剣を取った。お前の剣は遅い。お前が一番よく知っている。\n「遅い剣は避けやすい。それも俺が一番よく知っている。」", "镜子拿起了你的剑。你的剑很慢，你最清楚。\n“慢的剑也好躲。这我同样最清楚。”");
        A("herald.hero.rogue.1", "그림자 칼날이 빛 아래 쓰러졌다.\n“…빛이 너무 많았어. 다음엔 그림자를 더 데려오지.”", "The Shadow Blade has fallen in the light.\n\"...Too much light. I'll bring more shadow next time.\"", "影の刃が光の下で倒れた。\n「……光が多すぎた。次はもっと影を連れてくる。」", "暗影之刃倒在了光下。\n“……光太多了。下次多带点影子来。”");
        A("herald.hero.rogue.2", "보물을 찾아 내려온 자가 보물 앞에서 쓰러졌다.\n“보물은 도망 안 가. 나도 안 가고.”", "One who came down for treasure has fallen in front of it.\n\"Treasure doesn't run. Neither do I.\"", "財宝を求めて降りてきた者が、財宝の前で倒れた。\n「宝は逃げない。俺も逃げない。」", "为宝藏而来的人，倒在了宝藏面前。\n“宝藏不会跑。我也不会。”");
        A("herald.hero.rogue.3", "등을 보인 놈부터 쓰러진다고 했다. 네가 등을 보였다.\n“…말이 씨가 됐군.”", "You said whoever shows their back falls first. You showed yours.\n\"...Should've kept that line to myself.\"", "背を見せた奴から倒れると言った。背を見せたのはお前だ。\n「……言った通りになったか。」", "你说过谁先露出后背谁先倒。露出后背的是你。\n“……一语成谶啊。”");
        A("herald.hero.rogue.4", "돌진은 무적이다. 멈춘 자리는 무적이 아니다.\n“착지 자리를 골라야 했어. 알아.”", "The dash is untouchable. Where it stops is not.\n\"Should've picked my landing. I know.\"", "突進は無敵だ。止まった場所は無敵ではない。\n「着地点を選ぶべきだった。分かってる。」", "突进时无敌。停下的地方不无敌。\n“该挑好落点的。我知道。”");
        A("herald.hero.rogue.5", "첫 죽음. 도적에게 죽음은 처음이 아닐 텐데.\n“들통난 건 처음이야.”", "A first death. Surely death is nothing new to a thief.\n\"Getting caught is.\"", "最初の死。盗賊にとって死は初めてではないだろう。\n「バレたのは初めてだ。」", "第一次死亡。对盗贼来说，死应该不是头一回吧。\n“被逮到是头一回。”");
        A("herald.hero.rogue.6", "왕관을 노렸는가.\n“왕관은 왕이 죽은 뒤에 챙기는 거야. 순서가 틀렸지.”", "Were you after the crown?\n\"You take the crown after the king's dead. Got the order wrong.\"", "王冠を狙ったか。\n「王冠は王が死んでから頂くもんだ。順番を間違えた。」", "你盯上王冠了？\n“王冠得等王死了再拿。顺序错了。”");
        A("herald.hero.archer.1", "사냥꾼이 사냥감이 되었다.\n“숲에서는 흔한 일이다. 자리가 바뀌는 것도 흔하지.”", "The hunter has become the hunted.\n\"Common, in the woods. So is changing places again.\"", "狩人が獲物になった。\n「森ではよくあること。立場が入れ替わるのもよくある。」", "猎人成了猎物。\n“在林子里很常见。再换回来也常见。”");
        A("herald.hero.archer.2", "숨이 바닥났다. 떨리는 활은 반밖에 쏘지 못한다.\n“완벽한 한 발이 숨을 돌려준다. 그 한 발을 서둘렀다.”", "You ran out of breath. A shaking bow fires at half strength.\n\"A perfect shot gives the breath back. I rushed that one shot.\"", "息が尽きた。震える弓は半分しか射てぬ。\n「完璧な一射が息を返してくれる。その一射を急いだ。」", "你气息耗尽了。颤抖的弓只能射出一半的力。\n“一箭完美就能把气息还回来。那一箭我急了。”");
        A("herald.hero.archer.3", "시위를 당기는 동안 너는 느리다. 느린 것은 맞는다.\n“그래서 당길 때를 고르는 거다. 이번엔 못 골랐고.”", "While you draw the string, you are slow, and slow things get hit.\n\"That's why you choose when to draw. This time I didn't.\"", "弦を引いている間、お前は遅い。遅いものは当たる。\n「だから引く時を選ぶ。今回は選べなかった。」", "拉弦的时候你很慢。慢的东西会挨打。\n“所以才要挑拉弓的时机。这次没挑好。”");
        A("herald.hero.archer.4", "화살통은 가득하다고 했다. 가득한 채 쓰러졌다.\n“화살은 남기는 게 아니라 아끼는 거다. …이번엔 너무 아꼈어.”", "You said the quiver was full. You fell with it still full.\n\"Arrows are to be spared, not left over. ...I spared too many.\"", "矢筒は満タンだと言った。満タンのまま倒れた。\n「矢は残すものじゃない、惜しむものだ。……今回は惜しみすぎた。」", "你说箭筒是满的。倒下时它还是满的。\n“箭是用来省的，不是用来剩的。……这次省过头了。”");
        A("herald.hero.archer.5", "왕은 짐승이 아니다. 흔적을 남기지 않는다.\n“남긴다. 사람들은 그걸 패턴이라 부르더군. 다음엔 읽겠다.”", "A king is no beast. He leaves no tracks.\n\"He does. People call them patterns. Next time I'll read them.\"", "王は獣ではない。痕跡を残さぬ。\n「残す。人はそれを型と呼ぶらしい。次は読む。」", "王不是野兽。他不留踪迹。\n“他留。人们管那叫招式。下次我会读。”");
        A("herald.hero.archer.6", "숲의 사냥꾼이 초원에서 쓰러졌다. 숲이 아니라서인가.\n“초원도 숲이었다. 슬라임이 삼키기 전에는.”", "The hunter of the woods has fallen in a meadow. Because it is not the woods?\n\"The meadow was woods, too. Before the slime swallowed it.\"", "森の狩人が草原で倒れた。森でないからか。\n「草原も森だった。スライムが飲み込む前は。」", "森林猎手倒在了草原。因为这不是森林？\n“草原以前也是森林。在史莱姆吞掉它之前。”");
        A("herald.hero.alch.1", "학자가 자기 실험에 쓰러졌다.\n“실험은 실패해도 데이터는 남지. 킬킬.”", "The scholar has fallen to his own experiment.\n\"An experiment can fail. The data stays. Heh heh.\"", "学者が自分の実験に倒れた。\n「実験は失敗してもデータは残る。くっくっく。」", "学者倒在了自己的实验里。\n“实验失败了，数据还在。嘿嘿。”");
        A("herald.hero.alch.2", "불안정도가 가득 차면 발밑에서 터진다. 네 발밑이었다.\n“대폭발 플라스크로 쏟아 냈어야 했어. 손이 늦었군.”", "When Instability fills, it bursts underfoot. It was your feet.\n\"Should've dumped it with the Great Blast Flask. Hands were slow.\"", "不安定度が満ちれば足元で弾ける。お前の足元だった。\n「大爆発フラスコで吐き出すべきだった。手が遅れたな。」", "不稳定度一满就会在脚下炸开。炸的是你的脚下。\n“该用大爆炸烧瓶倾泻掉的。手慢了。”");
        A("herald.hero.alch.3", "되살아난 시체를 재료라 불렀다. 지금 너도 재료인가.\n“…좋은 재료지. 아깝게도.”", "You called the risen dead \"material.\" Are you material now?\n\"...Fine material, too. What a waste.\"", "蘇った死体を材料と呼んだ。今はお前も材料か。\n「……良い材料だよ。惜しいことに。」", "你把复活的尸体叫做材料。现在你也是材料了？\n“……还是上等材料。可惜了。”");
        A("herald.hero.alch.4", "세 가지 시약, 한 가지 죽음.\n“넷째 시약이 필요하단 뜻이군. 메모.”", "Three reagents, one death.\n\"So a fourth reagent is called for. Noted.\"", "三つの試薬、一つの死。\n「四つ目の試薬が要るってことか。メモ。」", "三种试剂，一种死法。\n“看来需要第四种试剂。记下了。”");
        A("herald.hero.alch.5", "첫 죽음. 논문에 쓸 만한가.\n“서론은 되겠어.”", "A first death. Good enough for a paper?\n\"Good enough for an introduction.\"", "最初の死。論文に使えるか。\n「序論にはなるな。」", "第一次死亡。能写进论文吗？\n“够写个引言。”");
        A("herald.hero.alch.6", "세상을 구한 것은 대부분 우연이었다고 했다. 이 죽음도 우연인가.\n“아니, 이건 실력이야. 모자란 쪽의.”", "You said saving the world was mostly luck. Was this death luck, too?\n\"No, this one was skill. The lack of it.\"", "世界を救ったのは大部分が偶然だと言った。この死も偶然か。\n「いや、これは実力だ。足りない方の。」", "你说拯救世界大多是偶然。这次死也是偶然吗？\n“不，这次是实力。不够的那种。”");
        A("herald.hero.carto.1", "측량사가 길을 잃었다.\n“길을 잃은 게 아니라 지도가 틀린 거다. 고치면 된다.”", "The surveyor has lost the way.\n\"Not lost. The map was wrong. It can be corrected.\"", "測量士が道に迷った。\n「迷ったんじゃない、地図が間違っていたんだ。直せばいい。」", "测量师迷路了。\n“不是迷路，是地图错了。改掉就好。”");
        A("herald.hero.carto.2", "그은 선이 끊겼다.\n“선은 다시 그으면 된다. 잉크는 많아.”", "The line you drew has broken off.\n\"A line can be drawn again. There's plenty of ink.\"", "引いた線が途切れた。\n「線はまた引けばいい。インクは山ほどある。」", "你画的线断了。\n“线可以重画。墨水多得是。”");
        A("herald.hero.carto.3", "세 획마다 도형이 닫힌다. 셋째 획 전에 쓰러졌다.\n“두 획은 선, 셋째가 도형. 다음엔 셋째부터 센다.”", "Every third stroke closes a shape. You fell before the third.\n\"Two strokes are lines; the third is the shape. Next time I count from the third.\"", "三本ごとに図形が閉じる。三本目の前に倒れた。\n「二本は線、三本目が図形。次は三本目から数える。」", "每三笔闭合一个图形。你倒在第三笔之前。\n“两笔是线，第三笔才是图形。下次从第三笔开始数。”");
        A("herald.hero.carto.4", "지도에 없는 곳에서 쓰러졌다.\n“그러니 그려야지. 「여기서 죽었다」— 첫 표기는 그걸로.”", "You fell somewhere not on the map.\n\"Then it must be drawn. 'Died here' — that will be the first mark.\"", "地図にない場所で倒れた。\n「なら描かなきゃ。『ここで死んだ』。最初の記号はそれにしよう。」", "你倒在地图上没有的地方。\n“那就得画上去。「死于此处」，第一个标注就用它。”");
        A("herald.hero.carto.5", "심연은 지도의 마지막 빈칸이다. 아직 비어 있다.\n“빈칸이 남았으니 돌아갈 이유가 있군.”", "The abyss is the last blank square on the map. It is still blank.\n\"A blank left means a reason to go back.\"", "深淵は地図の最後の空欄だ。まだ空いている。\n「空欄が残っているなら、戻る理由があるな。」", "深渊是地图上最后一格空白。它还空着。\n“还留着空格，就有回去的理由。”");
        A("herald.hero.carto.6", "선을 긋는 동안 적이 선 안으로 들어왔다.\n“지도 접기로 선 위에 올려 짓이겼어야 했어. 접는 걸 잊었다.”", "While you drew the line, the enemy stepped inside it.\n\"Should've folded the map and crushed them on the crease. I forgot to fold.\"", "線を引いている間に、敵が線の内へ入ってきた。\n「地図折りで線の上に乗せて潰すべきだった。折るのを忘れた。」", "你画线的时候，敌人走进了线内。\n“该用折叠地图把它们拉到线上碾碎的。忘了折。”");
        A("herald.hero.clock.1", "시계공의 시간이 멈췄다.\n“멈춘 시계를 고치는 게 내 일이다. 내 것이라도.”", "The clockmaker's time has stopped.\n\"Fixing stopped clocks is my trade. Even when the clock is mine.\"", "時計職人の時が止まった。\n「止まった時計を直すのが私の仕事だ。自分のものでもな。」", "钟表匠的时间停了。\n“修停掉的钟是我的本行。哪怕是我自己的。”");
        A("herald.hero.clock.2", "삼 초 전으로 돌아갈 수 있었다. 돌아가지 않았다.\n“되감기는 삼 초다. 틀린 건 네 초 전이었고.”", "You could have gone back three seconds. You didn't.\n\"The rewind is three seconds. The mistake was four seconds ago.\"", "三秒前へ戻れた。戻らなかった。\n「巻き戻しは三秒だ。間違えたのは四秒前だった。」", "你本可以回到三秒前。你没回。\n“倒带只有三秒。出错是在四秒前。”");
        A("herald.hero.clock.3", "늘 조금 일찍 준비한다고 했다. 이번엔 조금 늦었다.\n“일 분 빠른 시계도 가끔 늦지. 바늘을 더 돌려 두겠다.”", "You said you always prepare a little early. This time you were a little late.\n\"Even a clock set a minute fast runs late sometimes. I'll turn the hands further.\"", "いつも少し早めに備えると言った。今回は少し遅かった。\n「一分進めた時計でも時には遅れる。針をもっと進めておこう。」", "你说总是早一点准备。这次你晚了一点。\n“拨快一分钟的钟偶尔也会慢。我再把指针多拨一些。”");
        A("herald.hero.clock.4", "정각이 울리기 전에 쓰러졌다.\n“눈금이 세 칸 남았었다. 그 세 칸을 못 채운 건 내 손이다.”", "You fell before the hour struck.\n\"Three ticks were left. The hand that failed to fill them was mine.\"", "正時が鳴る前に倒れた。\n「目盛りが三つ残っていた。その三つを満たせなかったのは私の手だ。」", "你倒在整点敲响之前。\n“还差三格刻度。没填满那三格的，是我的手。”");
        A("herald.hero.clock.5", "왕은 시간을 거꾸로 감는 자다. 네 시계와 어느 쪽이 빠른가.\n“내 시계. 다음엔 증명한다.”", "The king is one who winds time backward. Which is faster, his or your clock?\n\"Mine. Next time I prove it.\"", "王は時を逆に巻く者だ。お前の時計とどちらが速い。\n「私の時計だ。次は証明する。」", "王是把时间倒着上发条的人。他和你的钟，哪个更快？\n“我的钟。下次证明给你看。”");
        A("herald.hero.clock.6", "다음은 언제 멈출지 안다고 했다.\n“알았다. 그래서 왔다. 또 멈추기 전에.”", "You said you knew when it would stop next.\n\"I did. That's why I came. Before it stops again.\"", "次にいつ止まるか分かると言った。\n「分かった。だから来た。また止まる前に。」", "你说你知道下次什么时候会停。\n“知道。所以我来了。在它再停之前。”");
        A("herald.hero.post.1", "배달부가 배달 도중에 쓰러졌다.\n“편지는 반드시 전해진다. 배달부가 바뀔 뿐… 아니, 내가 전한다.”", "The courier has fallen mid-delivery.\n\"Every letter gets delivered. Only the courier changes... No. I deliver it.\"", "配達人が配達の途中で倒れた。\n「手紙は必ず届けられる。配達人が替わるだけ……いや、私が届ける。」", "信使倒在了投递途中。\n“信件一定会送达。只是换个信使……不，我来送。”");
        A("herald.hero.post.2", "가방에 편지가 남았다.\n“남은 편지는 반송하지 않아. 다시 돈다.”", "There are letters left in the bag.\n\"Leftover letters don't go back to sender. I make the rounds again.\"", "かばんに手紙が残った。\n「残った手紙は返送しない。もう一度回る。」", "包里还剩着信。\n“剩下的信不退回。再跑一趟。”");
        A("herald.hero.post.3", "편지는 가장 먼 적부터 찾아간다. 가장 가까운 적은 누가 맡는가.\n“…속달이 맡아야 했지. 손이 느렸다.”", "Letters seek the farthest enemy first. Who takes care of the nearest?\n\"...Express Delivery should have. My hand was slow.\"", "手紙は最も遠い敵から探しに行く。最も近い敵は誰が受け持つ。\n「……速達が受け持つべきだった。手が遅かった。」", "信件先去找最远的敌人。最近的敌人谁来管？\n“……该由特快来管的。手慢了。”");
        A("herald.hero.post.4", "수취인이 죽은 자인 편지가 있다. 보낸 이도 죽은 자다. 너는 어느 쪽인가.\n“배달부. 그 둘 사이에 서 있는 자.”", "There are letters whose addressee is dead. So is the sender. Which are you?\n\"The courier. The one standing between the two.\"", "宛先が死者の手紙がある。差出人も死者だ。お前はどちらだ。\n「配達人。その二つの間に立つ者だ。」", "有的信收件人是死者。寄信人也是死者。你是哪一边？\n“信使。站在两者之间的人。”");
        A("herald.hero.post.5", "리치 왕에게 보내는 편지 — 「이제 그만 재워 줘」. 전하지 못했다.\n“수취인이 받기를 거부하면 손에 쥐여 주는 게 규칙이다. 다시 간다.”", "The letter to the Lich King: \"Let us rest now.\" It was not delivered.\n\"When the addressee refuses, the rule is to press it into his hand. I'm going back.\"", "リッチ王への手紙。「もう眠らせて」。届けられなかった。\n「宛先が受け取りを拒めば、手に握らせるのが規則だ。もう一度行く。」", "寄给巫妖王的信：「让我们安息吧」。没送到。\n“收件人拒收，规矩是塞到他手里。我再去。”");
        A("herald.hero.post.6", "붉은 사막의 소인이 찍힌 편지. 네 가방 바닥에 있던 것이다.\n“그 편지는 아직 열지 않았다. 열 때가 아니니까.”", "The letter postmarked from the red desert. It was at the bottom of your bag.\n\"I haven't opened that one. It isn't time.\"", "赤い砂漠の消印が押された手紙。お前のかばんの底にあったものだ。\n「あの手紙はまだ開けていない。開ける時じゃないからな。」", "盖着红色沙漠邮戳的信。它就在你包底。\n“那封信我还没打开。还不到时候。”");
        A("herald.hero.ghost.1", "죽은 자가 또 죽었다.\n“두 번째는 덜 아프더군.”", "The dead have died again.\n\"The second time hurts less.\"", "死者がまた死んだ。\n「二度目は、あまり痛くなかった。」", "死者又死了一次。\n“第二次没那么痛。”");
        A("herald.hero.ghost.2", "둘레에 거느린 영혼이 없었다. 맞은 것은 네 몸이었다.\n“영혼을 모아 두는 걸 잊었다. 나도 영혼인데.”", "There were no souls orbiting you. What took the blow was your own body.\n\"I forgot to gather souls. And I am one.\"", "周りにまとう魂がなかった。当たったのはお前の体だった。\n「魂を集めておくのを忘れた。私も魂なのに。」", "你身边没有环绕的灵魂。挨打的是你自己的身体。\n“忘了收集灵魂。我自己也是灵魂呢。”");
        A("herald.hero.ghost.3", "빙의한 동안은 무적이다. 나온 뒤가 문제였다.\n“터뜨리고 나올 자리를 봐야 했지. 안이 너무 편했다.”", "While possessing, you were untouchable. The trouble was after you came out.\n\"Should've watched where I'd land when it burst. It was too comfortable inside.\"", "憑依している間は無敵だ。問題は出た後だった。\n「破裂させて出る場所を見るべきだった。中が居心地よすぎた。」", "附身时你无敌。问题在于出来之后。\n“该看好引爆后落在哪的。里面太舒服了。”");
        A("herald.hero.ghost.4", "지켜야 할 것이 남았다고 했다. 아직 지키지 못했다.\n“그래서 아직 떠나지 못하는 거다.”", "You said there was still something to protect. You have not protected it yet.\n\"That's why I still can't leave.\"", "守るべきものが残っていると言った。まだ守れていない。\n「だからまだ旅立てないんだ。」", "你说还有要守护的东西。你还没守住。\n“所以我才还走不了。”");
        A("herald.hero.ghost.5", "오래전 이 초원에서 죽었다. 같은 자리인가.\n“…비슷하다. 그때도 혼자였고.”", "You died in this meadow long ago. Is this the same spot?\n\"...Close to it. I was alone that time, too.\"", "ずっと昔この草原で死んだ。同じ場所か。\n「……近い。あの時も一人だった。」", "很久以前你死在这片草原。是同一个地方吗？\n“……差不多。那时也是一个人。”");
        A("herald.hero.ghost.6", "거울이 네게 살아 있던 얼굴을 보여 주었는가.\n“보여 줬다. 그래서 늦었다.”", "Did the mirror show you the face you had when you were alive?\n\"It did. That's why I was late.\"", "鏡はお前に、生きていた頃の顔を見せたか。\n「見せた。だから遅れた。」", "镜子让你看见了活着时的脸吗？\n“看见了。所以慢了一步。”");
        A("herald.any.01", "쓰러졌다. 그러나 네가 쓰러뜨린 것들은 다시 서지 않는다. 그 수가 네 포인트다.", "You fell. But what you felled does not rise again. Their number is your points.", "倒れた。だがお前が倒したものは再び立たぬ。その数がお前のポイントだ。", "你倒下了。但你击倒的东西不会再站起来。它们的数目就是你的点数。");
        A("herald.any.02", "심연은 모든 것을 기억한다. 네가 어디서 멈췄는지도.", "The abyss remembers everything, including where you stopped.", "深淵はすべてを覚えている。お前がどこで止まったかも。", "深渊记得一切，包括你在哪里停下。");
        A("herald.any.03", "이 죽음은 끝이 아니라 쉼표다. 문장은 다음 판에 이어진다.", "This death is not a full stop but a comma. The sentence continues next run.", "この死は終わりではなく読点だ。文は次のプレイへ続く。", "这次死亡不是句号，是逗号。句子在下一局继续。");
        A("herald.any.04", "전령은 위로하지 않는다. 본 것만 말한다 — 너는 끝까지 싸웠다.", "The Herald does not console. It says only what it saw: you fought to the end.", "使者は慰めぬ。見たことだけを言う。お前は最後まで戦った。", "使者不安慰。只说看见的：你战到了最后。");
        A("herald.any.05", "오늘의 너는 어제의 너보다 멀리 왔다. 결과 화면이 그것을 안다.", "Today's you came farther than yesterday's. The result screen knows it.", "今日のお前は昨日のお前より遠くへ来た。結果画面がそれを知っている。", "今天的你比昨天走得更远。结果画面知道。");
        A("herald.any.06", "거울의 군주는 네가 쓰러뜨린 것의 메아리. 네가 많이 쓰러뜨릴수록 그도 커진다. 두려워할 일이 아니라 자랑할 일이다.", "The Mirror Sovereign is the echo of what you have slain. The more you slay, the greater he grows. That is nothing to fear. It is something to be proud of.", "鏡の君主はお前が倒したものの残響。多く倒すほど奴も大きくなる。恐れることではない。誇ることだ。", "镜之君主是你所击败之物的回响。你击败得越多，他就越强。这不是该怕的事，是该骄傲的事。");
        A("herald.any.07", "네가 쓰러뜨린 것들이 남긴 포인트는 사라지지 않았다. 네 다음 영웅의 값이다.", "The points from what you felled were not lost. They are the price of your next hero.", "お前が倒したものが残したポイントは消えていない。お前の次の英雄の値だ。", "你击倒之物留下的点数并未消失。那是你下一位英雄的价钱。");
        A("herald.any.08", "죽음은 공평하다 — 아홉 영웅 모두 같은 땅에 쓰러진다. 일어나는 법만 다르다.", "Death is fair: all nine heroes fall on the same ground. Only the way they rise differs.", "死は公平だ。九人の英雄は皆同じ地に倒れる。立ち上がり方だけが違う。", "死亡是公平的，九位英雄都倒在同一片土地上。只有站起来的方式不同。");
        A("herald.any.09", "여기까지 오는 데 쓴 시간은 사라지지 않는다. 다음 판은 그 시간 위에서 시작한다.", "The time it took to come this far is not lost. The next run begins on top of it.", "ここまで来るのに使った時間は消えぬ。次のプレイはその時間の上から始まる。", "走到这里花的时间不会消失。下一局从这段时间之上开始。");
        A("herald.any.10", "전령은 매번 다른 말을 한다. 네가 매번 다르게 쓰러지기 때문이다. 그것이 성장이다.", "The Herald says something different every time, because you fall differently every time. That is growth.", "使者は毎度違うことを言う。お前が毎度違う倒れ方をするからだ。それが成長だ。", "使者每次说的都不同，因为你每次倒下的方式都不同。这就是成长。");
        A("herald.any.11", "체력바 옆 보루 표시가 꺼져 있었다면, 보루는 이미 너를 한 번 살렸던 것이다. 두 번째는 네 몫이다.", "If the Last Stand mark beside your health bar was dark, the Stand had already saved you once. The second time is on you.", "体力バーの横の砦の印が消えていたなら、砦はすでに一度お前を救っていたのだ。二度目はお前の分だ。", "若生命条旁的堡垒标记已经暗了，说明堡垒已救过你一次。第二次得靠你自己。");
        A("herald.any.12.h", "결과 화면의 「준 피해」 첫 줄을 보라. 네가 가장 믿은 것이 거기 있다. 「받은 피해」 첫 줄도 보라. 네가 가장 소홀한 것이 거기 있다.", "Look at the first line under Damage Dealt on the result screen; what you trusted most is there. Look at the first line under Damage Taken, too; what you neglected most is there.", "結果画面の「与ダメージ」の一行目を見よ。お前が最も信じたものがそこにある。「被ダメージ」の一行目も見よ。お前が最も疎かにしたものがそこにある。", "看结果画面「造成伤害」的第一行，你最信赖的东西在那里。也看看「承受伤害」的第一行，你最疏忽的东西在那里。");
        A("herald.any.13", "죽음을 세는 자는 멈추고, 처치를 세는 자는 계속한다. 네 처치 수는 결과 화면에 있다.", "Those who count deaths stop. Those who count kills go on. Your kill count is on the result screen.", "死を数える者は止まり、撃破を数える者は続ける。お前の撃破数は結果画面にある。", "数死亡的人会停下，数击杀的人会继续。你的击杀数在结果画面上。");
        A("herald.any.14", "영웅은 쓰러진다. 영웅이 아닌 자는 오지 않는다.", "Heroes fall. Those who are not heroes never come at all.", "英雄は倒れる。英雄でない者は、そもそも来ない。", "英雄会倒下。不是英雄的人，根本不会来。");
        A("herald.any.15", "매 판 계약 셋 중 이룬 것은 이미 네 것이다. 쓰러져도 돌려주지 않는다.", "Whatever you fulfilled of this run's three contracts is already yours. Falling does not give it back.", "このプレイの三つの契約の内、果たしたものはすでにお前のものだ。倒れても返しはせぬ。", "本局三份契约里你完成的，已经属于你。倒下也不会收回。");
        A("herald.any.16", "이루지 못한 계약은 다음 판으로 넘어간다. 아깝게 놓친 것은 실패가 아니라 예약이다.", "An unfulfilled contract carries into the next run. A near miss is not a failure. It is a reservation.", "果たせなかった契約は次のプレイへ持ち越される。惜しくも逃したものは失敗ではなく、予約だ。", "没完成的契约会延续到下一局。差一点错过的不是失败，是预约。");
        A("herald.any.17", "한 판은 열다섯 분 안팎. 열다섯 분 뒤의 너는 늘 조금 다른 사람이다.", "A run is fifteen minutes or so. The you of fifteen minutes later is always a slightly different person.", "1プレイは十五分前後。十五分後のお前は、いつも少し違う人間だ。", "一局大约十五分钟。十五分钟后的你，总是略有不同的人。");
        A("herald.any.18.h", "쓰러진 곳의 줄을 읽었는가. 전령이 할 말은 그 줄에 다 들어 있다.", "Have you read the \"Fell to\" line? Everything the Herald could say is already in that line.", "「倒れた原因」の行を読んだか。使者の言うことは、その行にすべて入っている。", "读过「倒下于」那一行了吗？使者要说的，那一行里全都有。");
        A("herald.any.19", "다음 판의 네게 전한다 — 지난 판의 너는 여기서 끝났다. 거기서부터 시작하라.", "A message for the you of the next run: the you of the last run ended here. Begin from there.", "次のプレイのお前に伝える。前のプレイのお前はここで終わった。そこから始めよ。", "转告下一局的你：上一局的你在这里结束。从那里开始。");
        A("herald.any.20", "어둠은 기록이다. 네가 지나온 장이 전부 적혀 있다.", "The dark is a record. Every chapter you passed through is written there.", "闇は記録だ。お前が通ってきた章がすべて記されている。", "黑暗是记录。你走过的每一章都写在那里。");
        A("herald.any.21", "메아리는 사라지지 않는다. 네가 쓰러뜨린 것도, 네가 쓰러진 것도.", "Echoes do not fade: not of what you felled, nor of your own fall.", "残響は消えぬ。お前が倒したものも、お前が倒れたことも。", "回响不会消散。你击倒的，和你倒下的，都不会。");
        A("herald.any.22", "두 번 같은 자리에 쓰러지는 자는 없다. 자리가 같아도 네가 다르다.", "No one falls in the same place twice. Even if the place is the same, you are not.", "二度同じ場所に倒れる者はいない。場所が同じでも、お前が違う。", "没有人会两次倒在同一个地方。即使地方相同，你也已不同。");
        A("herald.any.23", "쓰러진 영웅의 등 뒤로 심연이 닫힌다. 다음에 열 때는 조금 더 밝을 것이다.", "The abyss closes behind the fallen hero. When it opens next, it will be a little brighter.", "倒れた英雄の背後で深淵が閉じる。次に開く時は、少し明るいだろう。", "深渊在倒下的英雄身后合上。下次打开时，会亮一点。");
        A("herald.any.24", "세상은 아직 구해지지 않았다. 그것은 네가 아직 필요하다는 뜻이다.", "The world is not yet saved. That means you are still needed.", "世界はまだ救われていない。それはお前がまだ必要だということだ。", "世界还没被拯救。那意味着还需要你。");
        A("herald.any.25.h", "쓰러진 뒤 가장 먼저 할 일은 결과를 읽는 것이다. 두 번째는 「다시」를 누르는 것.", "The first thing to do after falling is to read the results. The second is to press Retry.", "倒れた後に最初にすることは結果を読むこと。二番目は「もう一度」を押すことだ。", "倒下后第一件事是读结果。第二件事是按下「再来」。");
        A("herald.any.26", "포인트는 쌓였다. 영웅 하나가 가까워졌다. 쓰러진 판도 판이다.", "The points piled up. A hero came closer. A fallen run is still a run.", "ポイントは積まれた。英雄が一人、近づいた。倒れたプレイもプレイだ。", "点数累积了。一位英雄更近了。倒下的一局也是一局。");
        A("herald.any.27", "네 손이 느린 것이 아니다. 적이 빨랐을 뿐이다. 다음엔 네가 빠르다.", "Your hands are not slow. The enemy was merely fast. Next time, you are the fast one.", "お前の手が遅いのではない。敵が速かっただけだ。次はお前が速い。", "不是你的手慢，只是敌人快。下次，快的是你。");
        A("herald.any.28", "길을 잃은 것이 아니다. 길의 끝을 하나 본 것이다.", "You did not lose the way. You saw where one way ends.", "道に迷ったのではない。道の終わりを一つ見たのだ。", "你没有迷路。你只是看到了一条路的尽头。");
        A("herald.any.29", "전령은 네 이름을 모른다. 네가 쓰러뜨린 것의 수만 안다. 그것으로 충분하다.", "The Herald does not know your name. It knows only the number of what you felled. That is enough.", "使者はお前の名を知らぬ。お前が倒したものの数だけを知っている。それで十分だ。", "使者不知道你的名字，只知道你击倒之物的数目。那就够了。");
        A("herald.any.30", "쓰러졌다는 말은 서 있었다는 말이다.", "To say you fell is to say you stood.", "倒れたということは、立っていたということだ。", "说你倒下了，就是说你曾站着。");
        A("herald.any.31", "화면이 붉어지는 그 일 초 — 거기서 전령은 네 판을 본다. 괜찮은 판이었다.", "That one second when the screen turns red: there the Herald watches your run. It was a good run.", "画面が赤くなるその一秒。そこで使者はお前のプレイを見る。悪くないプレイだった。", "屏幕泛红的那一秒，使者在那里看你这一局。打得不错。");
        A("herald.any.32", "결과 화면의 숫자는 네가 아니다. 다음 판의 네가 넘을 선이다.", "The numbers on the result screen are not you. They are the line the next you will cross.", "結果画面の数字はお前ではない。次のプレイのお前が越える線だ。", "结果画面上的数字不是你。它们是下一局的你要跨过的线。");
        A("herald.any.33", "쓰러진 자리마다 이야기가 하나 남는다. 도감 「이야기」 탭의 기억은 그렇게 모인다.", "Every place you fall leaves a story behind. That is how the memories in the Codex's Story tab are gathered.", "倒れた場所ごとに物語が一つ残る。図鑑の「物語」タブの記憶は、そうして集まる。", "每一处你倒下的地方，都会留下一段故事。图鉴「故事」页里的记忆，就是这样攒起来的。");
        A("herald.any.34", "죽음이 아무것도 남기지 않던 시절이 있었다. 지금은 아니다 — 계약, 기억, 포인트.", "There was a time when death left nothing behind. Not anymore: contracts, memories, points.", "死が何も残さなかった時代があった。今は違う。契約、記憶、ポイント。", "曾有一个时代，死亡什么都不留下。现在不同了：契约、记忆、点数。");
        A("herald.any.35", "저승은 배달부에게도, 기사에게도, 총잡이에게도 같은 말을 한다. 다시 오라.", "The underworld says the same thing to the courier, the knight and the gunslinger alike: come again.", "冥府は配達人にも、騎士にも、ガンマンにも同じことを言う。また来よ。", "冥府对信使、对骑士、对枪手说的都是同一句：再来。");
        A("herald.any.36", "쓰러진 뒤 삼 초. 그 삼 초가 전령의 전부다. 길게 붙잡지 않겠다.", "Three seconds after you fall. Those three seconds are all the Herald has. It will not keep you long.", "倒れた後の三秒。その三秒が使者のすべてだ。長くは留めぬ。", "倒下后的三秒。那三秒就是使者的全部。不会久留你。");
        A("herald.any.37.h", "네가 본 것 중 가장 무서운 것은 무엇이었나. 다음 판에 그것부터 보라.", "What was the most frightening thing you saw? Next run, look at that first.", "お前が見た中で最も恐ろしかったものは何だ。次のプレイでは、それから見よ。", "你见过的东西里，最可怕的是什么？下一局，先看它。");
        A("herald.any.38", "끝은 늘 조금 더 멀리 있다. 그래서 다시 가는 것이다.", "The end is always a little farther off. That is why you go again.", "終わりはいつも少し先にある。だからまた行くのだ。", "终点总是再远一点。所以才要再去。");
        A("herald.any.39", "쓰러지는 법을 배운 자가 서는 법도 배운다.", "Whoever learns how to fall learns how to stand.", "倒れ方を学んだ者が、立ち方も学ぶ。", "学会了怎么倒下的人，也会学会怎么站起。");
        A("herald.any.40", "오늘 몇 번째인가. 세지 마라. 전령도 세지 않는다.", "How many times today? Don't count. The Herald doesn't either.", "今日で何度目か。数えるな。使者も数えぬ。", "今天第几次了？别数。使者也不数。");
        A("herald.any.41", "일어나는 데 필요한 것은 하나다 — 「다시」. 나머지는 이미 네 안에 있다.", "Rising takes one thing: Retry. Everything else is already in you.", "立ち上がるのに要るものは一つ。「もう一度」。残りはもうお前の中にある。", "站起来只需要一样东西：「再来」。其余的都已在你心里。");
        A("herald.any.42", "심연은 깊다. 그러나 네가 내려온 만큼은 이미 환하다.", "The abyss is deep. But as far down as you have come, it is already lit.", "深淵は深い。だがお前が降りてきた分は、すでに明るい。", "深渊很深。但你走下来的这一段，已经亮了。");
        A("herald.any.43", "이 판의 처치 수를 보라. 그만큼의 메아리가 네 편이다.", "Look at this run's kill count. That many echoes are on your side.", "このプレイの撃破数を見よ。それだけの残響がお前の味方だ。", "看看这一局的击杀数。那么多的回响都站在你这边。");
        A("herald.any.44", "영웅의 죽음은 세상의 죽음이 아니다. 세상은 네가 돌아오기를 기다릴 줄 안다.", "A hero's death is not the world's death. The world knows how to wait for you to return.", "英雄の死は世界の死ではない。世界はお前が戻るのを待つことを知っている。", "英雄的死不是世界的死。世界懂得等你回来。");
        A("herald.any.45", "거울은 네 힘을 되비친다. 그러니 거울이 셀수록 네가 센 것이다.", "The mirror reflects your strength. So the stronger the mirror, the stronger you.", "鏡はお前の力を映し返す。ゆえに鏡が強いほど、お前が強いのだ。", "镜子映照你的力量。所以镜子越强，就是你越强。");
        A("herald.any.46", "전령이 마지막으로 전한다 — 또 보자.", "The Herald's last word: see you again.", "使者が最後に伝える。また会おう。", "使者最后一句：再见。");
        A("herald.brand.tide.h", "영혼의 밀물 — 적이 사분의 일 더 자주 온다. 경험치도 그만큼 더. 밀물에 쓰러진 자는 물러설 자리를 미리 두지 않은 자다. 벽을 등지지 말고 늘 빈 땅을 뒤에 두라.", "Soul Tide: enemies come a quarter more often, and so does the EXP. Whoever falls in the tide is one who kept no room to retreat. Keep open ground behind you, never a wall.", "魂の満ち潮。敵が四分の一多く来る。経験値もその分多く。満ち潮に倒れた者は退く場所を先に確保しなかった者だ。壁を背にせず、常に空いた地を後ろに置け。", "灵魂涨潮：敌人来得多四分之一，经验也多四分之一。倒在潮里的，是没提前留退路的人。别背靠墙，身后永远留一片空地。");
        A("herald.brand.giant.h", "거인 사냥꾼은 보스를 네 할 더 단단하게 하고 네 필살기를 절반 더 빨리 채운다. 그 각인은 「보스전에서 필살기를 아끼지 않겠다」는 약속이다. 아꼈다면 각인이 아니라 네가 틀렸다.", "Giant Hunter makes bosses forty percent tougher and fills your Ultimate half again as fast. That brand is a promise not to hoard your Ultimate in boss fights. If you hoarded it, the brand was not wrong. You were.", "巨人狩りはボスを四割硬くし、お前の必殺技を半分速く満たす。あの刻印は「ボス戦で必殺技を惜しまぬ」という約束だ。惜しんだなら、刻印ではなくお前が間違えた。", "巨人猎手让首领硬四成，也让你的必杀充能快一半。那枚烙印是「首领战不省必杀」的承诺。若你省了，错的不是烙印，是你。");
        A("herald.brand.iron.h", "무쇠 맹세를 두르고도 쓰러졌다. 사분의 일 덜 맞는데도 쓰러졌다면 맞은 횟수가 문제다 — 적이 오래 살았다는 뜻이고, 그것은 공격력 일 할 오 푼의 값이다. 다음엔 공격 카드를 먼저 쥐어라.", "You fell even wearing the Iron Oath. If a quarter less damage still wasn't enough, the trouble was how many times you were hit: enemies lived too long, and that is the price of fifteen percent less attack. Next time, take attack cards first.", "鉄の誓いをまとっても倒れた。四分の一少なく当たってなお倒れたなら、問題は当たった回数だ。敵が長く生きたということで、それは攻撃力一割五分の代価だ。次は攻撃のカードを先に取れ。", "披着钢铁誓约也倒下了。少挨四分之一还倒下，问题就在挨打的次数：敌人活得太久，那是少一成五攻击力的代价。下次先拿攻击卡。");
        A("herald.brand.greed.h", "탐욕 — 적은 세 할 더 단단하고 보상은 여섯 할 더. 탐욕에 쓰러지는 자는 늘 같은 자리에서 쓰러진다: 더 단단해진 2장의 첫 일 분. 거기서만 물러서며 싸우면 나머지는 이자다.", "Greed: enemies thirty percent tougher, rewards sixty percent richer. Those who fall to Greed always fall in the same place, the first minute of a hardened Chapter 2. Fight that minute backing away, and the rest is interest.", "強欲。敵は三割硬く、報酬は六割多い。強欲に倒れる者はいつも同じ場所で倒れる。硬くなった二章の最初の一分だ。そこだけ退きながら戦えば、残りは利息だ。", "贪婪：敌人硬三成，奖励多六成。被贪婪放倒的人总倒在同一处：变硬的第2章头一分钟。只在那一分钟边退边打，其余都是利息。");
        A("herald.brand.frenzy.h", "광란은 적을 두 할 빠르게, 스킬을 세 할 잦게 한다. 경고가 더 자주 뜨고 더 빨리 닫힌다는 뜻이다. 광란의 판에서는 경고를 끝까지 보지 마라 — 뜨는 순간 비켜라.", "Frenzy makes enemies twenty percent faster and their skills thirty percent more frequent. That means warnings appear more often and close faster. In a Frenzy run, don't watch a warning to its end; step off the moment it appears.", "狂乱は敵を二割速く、スキルを三割頻繁にする。警告がより多く出て、より早く閉じるということだ。狂乱のプレイでは警告を最後まで見るな。出た瞬間に退け。", "狂乱让敌人快两成，技能频率高三成。意思是预警出现得更多、关闭得更快。狂乱的局里别把预警看到底，出现的那一刻就躲。");
        A("herald.brand.blood.h", "피의 계약 — 최대 체력 네 할을 내주었다. 보스의 한 방 상한도 그만큼 내려갔으니 보스전에서는 두 번이 아니라 세 번을 맞을 수 있다. 그러나 잡몹 사이에서는 그 셋이 금방이다. 보스보다 잡몹을 두려워하라.", "Blood Pact: you gave up forty percent of your maximum health. A boss's single-blow cap fell with it, so in a boss fight you can take three hits instead of two. But among the crowd those three come fast. Fear the minions more than the boss.", "血の契約。最大体力の四割を差し出した。ボスの一撃の上限もその分下がり、ボス戦では二度ではなく三度当たれる。だが雑兵の中ではその三度がすぐだ。ボスより雑兵を恐れよ。", "鲜血契约，你交出了四成最大生命。首领的单击上限也随之下降，所以首领战里你能挨三下而非两下。可在杂兵群中，那三下来得很快。比首领更要怕杂兵。");
        A("herald.brand.calm.h", "고요 — 적은 느리고 네 필살기는 더디다. 고요의 판에서 쓰러진 자는 필살기를 기다리다 쓰러진 자다. 고요는 필살기 없이 평타로 끝내는 판이다. 평타 카드를 쥐어라.", "Stillness: enemies are slow and your Ultimate is slower. Whoever falls in a Stillness run fell while waiting for the Ultimate. Stillness is a run you finish with basic attacks, not Ultimates. Take the cards that feed them.", "静寂。敵は遅く、お前の必殺技はもっと遅い。静寂のプレイで倒れた者は、必殺技を待って倒れた者だ。静寂は必殺技なしで通常攻撃で終えるプレイだ。通常攻撃のカードを取れ。", "寂静：敌人慢，你的必杀更慢。倒在寂静局里的人，是等必杀时倒下的人。寂静是靠普攻而非必杀打完的局。拿普攻的卡。");
        A("herald.brand.tyrant.h", "폭군의 왕관은 보스를 여섯 할 더 길게, 네 상처를 두 할 더 깊게 한다. 긴 보스전에서 깊은 상처 — 결계가 더 자주 온다는 뜻이기도 하다. 왕관을 쓴 판에서는 결계를 두 번 넘길 각오로 들어가라.", "Tyrant's Crown makes bosses sixty percent longer and your wounds twenty percent deeper. Long boss fights with deep wounds also mean barriers come more often. Enter a crowned run ready to outlive the barrier twice.", "暴君の王冠はボスを六割長く、お前の傷を二割深くする。長いボス戦に深い傷。結界がより多く来るということでもある。王冠のプレイには、結界を二度越える覚悟で入れ。", "暴君之冠让首领战长六成，让你的伤深两成。漫长的首领战加深重的伤，也意味着结界来得更勤。戴冠的局，要做好熬过两次结界的准备。");
        A("herald.brand.surge.h", "마력 폭주 — 네 필살기는 여덟 할 빨리 차고 적의 스킬은 네 할 잦다. 필살기가 그렇게 자주 차는데도 쓰러졌다면, 찬 것을 쏟지 않은 것이다. 폭주의 판에서 게이지는 가득 차 있을 틈이 없어야 한다.", "Mana Surge: your Ultimate fills eighty percent faster and enemy skills come forty percent more often. If your Ultimate filled that often and you still fell, you did not spend what filled. In a Surge run the gauge should never have time to sit full.", "魔力暴走。お前の必殺技は八割速く満ち、敵のスキルは四割頻繁だ。それほど必殺技が満ちてなお倒れたなら、満ちたものを注がなかったのだ。暴走のプレイでは、ゲージが満ちたままでいる暇はあってはならぬ。", "魔力暴走：你的必杀充能快八成，敌人技能频率高四成。必杀充得那么快还倒下，说明你没把充满的倾泻出去。暴走的局里，充能槽不该有停在满格的时间。");
        A("boss.again.lich", "…또 너냐. 묘역은 잠들 틈이 없군.", "...You again. My catacombs never get to sleep.", "……また貴様か。墓所は眠る暇もない。", "……又是你。墓穴连睡的空都没有。");
        A("boss.again5.lich", "몇 번을 재워도 돌아오는 망자여.", "You, who return however often I lay you down.", "幾度眠らせても戻る亡者よ。", "无论安葬几次都会归来的亡者啊。");
        A("boss.again.demon", "하찮은 인간이 또 문턱을 넘었군.", "The worthless human crosses my threshold again.", "取るに足らぬ人間がまた門をくぐったか。", "卑微的人类又跨过了门槛。");
        A("boss.again5.demon", "불길이 너를 기억한다. 재가 되지 않는 자.", "My flames remember you, the one who will not burn.", "炎が貴様を覚えている。灰にならぬ者。", "烈焰记得你，不化为灰烬的人。");
        A("boss.again.slime", "뿌요… 또 식탁에 올라왔구나!", "Puyo... Back on my dinner table again!", "ぷよ……また食卓に上がってきたな！", "噗哟……又爬上我的餐桌了！");
        A("boss.again5.slime", "뿌요요… 너는 안 녹는 밥이구나.", "Puyoyo... You're the meal that won't melt.", "ぷよよ……お前は溶けない飯か。", "噗哟哟……你是溶不掉的饭啊。");
        A("boss.again.mirror", "…네 메아리가 하나 늘었군.", "...Your echo has grown by one.", "……お前の残響がひとつ増えたな。", "……你的回响又多了一道。");
        A("boss.again5.mirror", "너를 몇 번 되비쳤는지 세지 않는다.", "I no longer count how often I have reflected you.", "お前を幾度映したかは数えぬ。", "映照你多少次，我已不数了。");
    }
}
